window.AUTH=window.AUTH||{};window.AUTH["20-1530"]={"d":"20-1530","id":"2021/20-1530","n":"West Virginia v. Environmental Protection Agency","briefs":[{"k":"petitioner","label":"Brief of petitioners West Virginia, et al.","date":"2021-12-13","url":"https://www.supremecourt.gov/DocketPDF/20/20-1530/204846/20211213135136223_WV%20v%20EPA%20-%20Opening%20Brief%20for%20WV.pdf","side":"pet","n":105},{"k":"petitioner","label":"Brief of petitioner The North American Coal Corporation","date":"2021-12-13","url":"https://www.supremecourt.gov/DocketPDF/20/20-1530/204904/20211213163113690_20-1530%20-%20NACCO%20Opening%20Merits%20Brief.pdf","side":"pet","n":53},{"k":"petitioner","label":"Brief of petitioner Westmoreland Minings Holdings LLC","date":"2021-12-13","url":"https://www.supremecourt.gov/DocketPDF/20/20-1530/204857/20211213141438218_20-1530%2020-1778%20Westmoreland%20Merits.pdf","side":"pet","n":51},{"k":"petitioner","label":"Brief of petitioner The State North Dakota","date":"2021-12-13","url":"https://www.supremecourt.gov/DocketPDF/20/20-1530/204918/20211213175459245_Merits%20Brief%20of%20Petitioner%20the%20State%20of%20North%20Dakota%2020-1530.pdf","side":"pet","n":30},{"k":"respondent","label":"Brief of respondent National Mining Association in support","date":"2021-12-13","url":"https://www.supremecourt.gov/DocketPDF/20/20-1530/204811/20211213122257995_20-1530_Brief%20in%20Support.pdf","side":"res","n":41},{"k":"respondent","label":"Brief of respondent Basin Electric Power Cooperative in support","date":"2021-12-13","url":"https://www.supremecourt.gov/DocketPDF/20/20-1530/204905/20211213163229496_2021-12-13%20Brief%20of%20Respondent%20Basin%20Electric%20Power%20Cooperative.pdf","side":"res","n":11},{"k":"respondent","label":"Brief of respondent America's Power","date":"2021-12-13","url":"https://www.supremecourt.gov/DocketPDF/20/20-1530/204917/20211213173428410_Americas%20Power_No.%2020-1530%20FINAL.pdf","side":"res","n":30},{"k":"respondent","label":"Brief of Federal respondents","date":"2022-01-18","url":"https://www.supremecourt.gov/DocketPDF/20/20-1530/210639/20220118211953209_20-1530bsUnitedStates.pdf","side":"res","n":80},{"k":"reply","label":"Reply of petitioner The North American Coal Corporation","date":"2022-02-17","url":"https://www.supremecourt.gov/DocketPDF/20/20-1530/214448/20220217143754919_20-1530%20-%20NACCO%20Reply%20Merits%20Brief.pdf","side":"pet","n":22},{"k":"reply","label":"Reply of petitioner Westmoreland Minings Holdings LLC in No. 20-1778","date":"2022-02-17","url":"https://www.supremecourt.gov/DocketPDF/20/20-1530/214421/20220217130206164_20-1530%20Reply%20Brief%20of%20Petitioner%20Westmoreland%20Mining%20Holdings%20LLC%20No.%2020-1778.pdf","side":"pet","n":30},{"k":"reply","label":"Reply of petitioner The State North Dakota in No. 20-1780","date":"2022-02-17","url":"https://www.supremecourt.gov/DocketPDF/20/20-1530/214467/20220217161443035_Reply%20Merits%20Brief%20of%20Petitioner%20the%20State%20of%20North%20Dakota%2020-1530.pdf","side":"pet","n":18},{"k":"reply","label":"Reply of petitioners State of West Virginia, et al.","date":"2022-02-17","url":"https://www.supremecourt.gov/DocketPDF/20/20-1530/214466/20220217155858111_Reply%20Brief.PDF","side":"pet","n":52}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/597us2r65_5iel.pdf","tr":true,"items":[{"t":"case","label":"A.L.A. Schechter Poultry Corp. v. United States","cite":"295 U.S. 495","y":1935,"id":"1900-1940/295us495","sc":1,"sum":"The Court held that the legislative branch cannot delegate to the President the authority to regulate industries without also providing standards or rules for doing so.","sumSrc":"Oyez","by":{"0":"46-47"}},{"t":"case","label":"Abuelhawa v. United States","cite":"556 U.S. 816","y":2009,"id":"2008/08-192","sc":1,"sum":"The Court found that using a telephone to make a misdemeanor drug purchase does not facilitate the felony of drug distribution.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Ala. Ass’n of Realtors v. Dep’t of Health & Hum. Servs.","cite":"141 S. Ct. 2485","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/2485/","sc":1,"sum":"Rejecting CDC’s “claim of expansive authority” to issue an eviction moratorium based in part on its “unprecedented” nature.","sumSrc":"brief:1","by":{"0":"16, 18, 20, 22, 24","1":"passim","4":"passim","6":"passim","7":"46","8":"5, 6, 7"}},{"t":"case","label":"Alaska Dep’t of Env’t Conservation v. EPA","cite":"540 U.S. 461","y":2004,"id":"2003/02-658","sc":1,"op":1,"sum":"The Court held that the Clean Air Act authorized the EPA to bar the construction of the polluting facility in Alaska. Though Alaska determined the facility's use of \"Low NOx\" met the act's requirement that facilities use \"best available control technology,\" the EPA was reasonable to reject this claim.","sumSrc":"Oyez","by":{"0":"28","3":"38, 40, 41, 42, 43","7":"29"}},{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Almendarez-Torres v. United States","cite":"523 U.S. 224","y":1998,"id":"1997/96-6839","sc":1,"sum":"The Court held that subsection (b)(2) of 8 USC section 1326(a) is a penalty provision, which authorizes a court to increase the sentence for a recidivist, and does not define a separate crime. \"[W]e note that the relevant statutory subject matter is recidivism,\" wrote Justice Breyer, \"[t]hat subject matter -- prior commission of a serious crime -- is as typical a sentencing factor as one might imagine.\" Therefore, neither subsection (b)(2) nor the due process clause of the Fifth Amendment required that the government charge a prior aggravated felony conviction in the alien's indictment for the imposition of a sentence more than 2 years.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Am. Elec. Power Co. v. Connecticut","cite":"564 U.S. 410","y":2011,"id":"2010/10-174","sc":1,"op":8,"sum":"The Court held that held the Clean Air Act bars suits by governmental bodies and private parties seeking to curb emissions from utilities via the federal common law.","sumSrc":"Oyez","by":{"0":"18","1":"4","3":"38, 39","7":"26, 42, 45","9":"15","10":"24, 25","11":"7"}},{"t":"case","label":"Am. Mun. Power-Ohio v. EPA","cite":"98 F.3d 1372","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/98/1372/","by":{"0":"3"}},{"t":"case","label":"Ark. Elec. Co-op Corp. v. Ark. Pub. Serv. Comm’n","cite":"461 U.S. 375","y":1983,"id":"1982/81-731","sc":1,"op":1,"sum":"Appellant is a customer-owned rural power cooperative established with loan funds and technical assistance provided by the federal Rural Electrification Administration (REA), but unlike most such cooperatives, which provide power directly to consumers, appellant's sole members and primary customers are 17 smaller Arkansas rural power cooperatives which in turn serve the ultimate consumer. Although tied into an …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","2":"6","4":"41"}},{"t":"case","label":"ASARCO Inc. v. EPA","cite":"578 F.2d 319","y":1978,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/578/319/","by":{"0":"40"}},{"t":"case","label":"AT&T Corp. v. Iowa Util. Bd.","cite":"525 U.S. 366","y":1999,"id":"1998/97-826","sc":1,"sum":"In a complicated split opinion, the Court held that the FCC has rulemaking authority to uphold those provision of the Act in question. Despite the local nature of some of the LECs involved, the Court emphasized their interconnectivity with regional and national carriers. As such, the FCC could also reach local LEC markets and regulate their competitive business practices.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Atl. City Elec. Co. v. FERC","cite":"295 F.3d 1","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/295/1/","by":{"0":"17"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"26","1":"39"}},{"t":"case","label":"Cent. Hudson Gas & Elec. Corp. v. Pub. Serv. Comm’n of N.Y.","cite":"447 U.S. 557","y":1980,"id":"1979/79-565","sc":1,"sum":"The Court overruled the Court of Appeals of New York and held that the New York's ban violated the right to commercial speech. Writing for the majority, Justice Lewis F. Powell cited the protections for \"commercial speech from unwarranted governmental regulation\" set forth in Virginia Pharmacy Board v. Virginia Citizens Consumer Council .","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. Nat. Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":4,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"43","1":"16, 17, 33","3":"34","4":"passim","6":"passim","7":"25"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"op":1,"sum":"The Court found that the courts must apply the Chevron doctrine and defer to an agency's interpretation of its jurisdiction when that jurisdiction is called into question.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"Cyan, Inc. v. Beaver Cnty. Emps. Ret. Fund","cite":"138 S. Ct. 1061","y":2018,"id":"2017/15-1439","sc":1,"sum":"The Court held that that the Securities Litigation Uniform Standards Act of 1998 does not strip state courts of jurisdiction to hear claims under the Securities Act of 1933, nor does it permit defendants to remove class actions alleging only 1933 Act claims from state to federal court.","sumSrc":"Oyez","by":{"0":"33, 39"}},{"t":"case","label":"Facebook, Inc. v. Duguid","cite":"141 S. Ct. 1163","y":2021,"id":"2020/18-956","sc":1,"sum":"Google’s limited copying of the Java SE Application Programming Interface allowed programmers to put their accrued talents to work in a transformative program and constituted a fair use of that material under copyright law.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36"}},{"t":"case","label":"FCC v. AT&T","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"op":1,"sum":"The Court held that corporations do not have a right of personal privacy that would prevent the disclosure of public records handed over to federal agencies.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"op":27,"ar":4,"sum":"Noting that for decades the FDA had said it lacked statutory power to regulate cigarettes.","sumSrc":"opinion","by":{"0":"2, 14, 16, 21, 23, 25","1":"17, 19, 26","2":"passim","4":"passim","6":"passim","7":"47","11":"3, 4"}},{"t":"case","label":"Fed. Power Comm’n v. La. Power & Light Co.","cite":"406 U.S. 621","y":1972,"id":"1971/71-1016","sc":1,"sum":"When United Gas Pipe Line Co. (United), a jurisdictional pipeline, experienced temporary shortages of natural gas supply forcing it to reduce deliveries to its contract customers, the Federal Power Commission (FPC) asserted its jurisdiction to effect a reasonable curtailment plan covering deliveries to both direct-sales customers and purchasers for resale. While curtailment proceedings were pending before the FPC, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"FERC v. Elec. Power Supply Ass’n","cite":"577 U.S. 260","y":2016,"id":"2015/14-840","sc":1,"sum":"The Court held that the Federal Power Act (FPA) grants the Federal Energy Regulatory Commission (FERC) the authority to regulate wholesale market operators’ compensation for reduction in electricity consumption, and the rule in question was not arbitrary and capricious.","sumSrc":"Oyez","by":{"0":"27, 29, 30, 41","2":"33–34","7":"39","9":"4","10":"16"}},{"t":"case","label":"FTC v. Bunte Bros.","cite":"312 U.S. 349","y":1941,"id":"scdb/1940-136","sc":1,"op":2,"sum":"1. The'Federal Trade Commission is without authority under § 5 of the Federal Trade Commission Act to prevent a candy manufacturer within a State from selling, wholly within that State, candy in so-called \"break and take\" assortments.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"op":11,"ar":1,"sum":"The Court decided that the Controlled Substance Act did not ban the use of controlled substances in physician-assisted suicide, nor does the Attorney General have the power to determine what is a violation of the Act.","sumSrc":"Oyez","by":{"0":"16, 18, 23, 24, 26","1":"19","2":"22, 25, 32, 34","4":"passim","6":"14, 16, 30","7":"46","11":"6, 7"}},{"t":"case","label":"Graham Cnty. Soil & Water Cons. Dist. v. U.S. ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"sum":"The Court held that an audit performed by a state or its political subdivisions constitutes an administrative report within the False Claims Act.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Gundy v. United States","cite":"139 S. Ct. 2116","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"15, 44, 45","1":"20, 21, 22, 27","2":"22, 41–42","4":"passim","6":"7, 8, 12","7":"50","9":"19"}},{"t":"case","label":"Herrmann v. Cencom Cable Assocs., Inc.","cite":"978 F.2d 978","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/978/978/","by":{"0":"33"}},{"t":"case","label":"Hodel v. Va. Surface Mining & Reclamation Ass’n, Inc.","cite":"452 U.S. 264","y":1981,"id":"1980/79-1538","sc":1,"sum":"In the context of a facial challenge, the Act is constitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Hughes v. Talen Energy Mktg., LLC","cite":"136 S. Ct. 1288","y":2016,"id":"2015/14-614","sc":1,"sum":"The Court determined that the Federal Power Act preempted state regulation of utility contracts and sales.","sumSrc":"Oyez","by":{"0":"27","2":"7, 40","4":"44","7":"26"}},{"t":"case","label":"Indus. Union Dept., AFL-CIO v. Am. Petroleum Inst.","cite":"448 U.S. 607","y":1980,"id":"1979/78-911","sc":1,"op":3,"sum":"The Court agreed with the Court of Appeals that the Secretary had acted without knowledge that the new standard was necessary to \"provide safe and healthful employment\" as mandated by the Act. Nothing in OSHA's administrative record indicated that exposure to benzene at 10 ppm would cause leukemia and that exposure to one ppm would not.","sumSrc":"Oyez","by":{"0":"16, 44","1":"17","2":"22, 41, 42, 44","4":"17, 18, 23","9":"19","11":"2"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Int’l Union, United Auto., Aerospace & Agr. Implement Workers of Am., UAW v. OSHA","cite":"938 F.2d 1310","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/938/1310/","by":{"0":"46"}},{"t":"case","label":"Intel Corp. Inv. Pol’y Comm. v. Sulyma","cite":"140 S. Ct. 768","y":2020,"id":"2019/18-1116","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"0":"44","11":"16"}},{"t":"case","label":"Janus v. Am. Fed’n of State, Cnty. & Mun. Emps., Council 31","cite":"138 S. Ct. 2448","y":2018,"id":"2017/16-1466","sc":1,"sum":"The Court decided the State of Illinois’ extraction of agency fees from nonconsenting public-sector employees violates the First Amendment; Abood v. Detroit Bd. of Ed., 431 U.S. 209 (1977), which held otherwise, was overruled.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"King v. Burwell","cite":"576 U.S. 473","y":2015,"id":"2014/14-114","sc":1,"op":7,"sum":"The Court determined that the plain language of the Affordable Care Act extended tax credits to federally-created exchanges as well as those the states created.","sumSrc":"Oyez","by":{"0":"16, 20, 24, 38","1":"19, 28","2":"25","4":"passim","6":"18"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"op":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"15"}},{"t":"case","label":"Koons Buick Pontiac GMC, Inc. v. Nigh","cite":"543 U.S. 50","y":2004,"id":"2004/03-377","sc":1,"sum":"In an 8-1 judgment delivered by Justice Ruth Bader Ginsburg, the Court held that a 1995 TILA amendment did not change the original limit on violations involving personal-property loans. Congress intended the amendment to raise the minimum and maximum recoveries for closed-end loans secured by real property. Congress had not sought to remove the $1,000 cap on loans secured by personal property.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Lawson v. Suwannee Fruit & S.S. Co.","cite":"336 U.S. 198","y":1949,"id":"scdb/1948-038","sc":1,"op":2,"sum":"Under § 8 (f) (1) of the Act, the employer was liable only for permanent partial disability (loss of the left eye), and the remainder of the compensation due for permanent total disability was payable out of the special fund established by § 44 of the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Life Techs. Corp. v. Promega Corp.","cite":"137 S. Ct. 734","y":2017,"id":"2016/14-1538","sc":1,"sum":"The Court held that supplying a single component of a multi-component invention from the United States for sale abroad does not expose the manufacturer to liability for infringement based on worldwide sales.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Marshall Field & Co. v. Clark","cite":"143 U.S. 649","y":1982,"id":"scdb/1891-139","sc":1,"op":4,"sum":"The signing by the Speaker of the House of Representatives and by the President of the Senate, in open session, of an enrolled bill, is an official attestation by the two Houses of such bill as one that has passed Congress; and when the bill thus attested receives the approval of the President, and is deposited in the Department of State according to law, its authentication as a bill that has passed Congress is …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"44","2":"42"}},{"t":"case","label":"Massachusetts v. EPA","cite":"549 U.S. 497","y":2007,"id":"2006/05-1120","sc":1,"op":6,"ar":1,"sum":"The Court ruled that states could sue the EPA for potential damage to their territory caused by global warming, and that the Clean Air Act imposes a duty upon the EPA to regulate the emissions of carbon dioxide and other gases that contribute to global warming.","sumSrc":"Oyez","by":{"0":"18, 25, 48","1":"6","4":"49","7":"18, 45","10":"6, 10","11":"7, 22"}},{"t":"case","label":"MCI Telecomms. Corp. v. Am. Tel. & Tel. Co.","cite":"512 U.S. 218","y":1994,"id":"1993/93-356","sc":1,"op":5,"sum":"The Commission's permissive detariffing policy is not a valid exercise of its §203(b)(2) authority to \"modify any requirement.\" Because virtually every dictionary in use now and at the time the statute was enacted defines \"to modify\" as meaning to change moderately or in minor fashion, the word \"modify\" must be seen to have a connotation of increment or limitation. That § 203(b)(2) does not contemplate basic or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 21, 36","2":"22–23, 25, 34","4":"16, 19","6":"13, 16, 26"}},{"t":"case","label":"Mexichem Fluor, Inc. v. EPA","cite":"866 F.3d 451","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/866/451/","by":{"0":"24","1":"43"}},{"t":"case","label":"Michigan v. EPA","cite":"268 F.3d 1075","y":2001,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/268/1075/","by":{"0":"1","2":"34","3":"6, 11, 30, 33"}},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"op":3,"sum":"The Court determined that the Environmental Protection Agency (EPA) unreasonably interpreted the Clean Air Act by not considering costs to power plants in deciding that regulation was “appropriate and necessary.”","sumSrc":"Oyez","by":{"0":"46","1":"4","2":"7","6":"7, 8","7":"3","10":"10, 11"}},{"t":"case","label":"Mohamad v. Palestinian Auth.","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"sum":"The Court held that the word \"individual\" in the Torture Victim Protection Act means a natural person and does not impose any liability against organizations.","sumSrc":"Oyez","by":{"0":"40","11":"15"}},{"t":"case","label":"Nat’l Asphalt Pavement Ass’n v. Train","cite":"539 F.2d 775","y":1976,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/539/775/","by":{"0":"35"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"0":"35","8":"19","11":"19"}},{"t":"case","label":"Nat’l Fed. of Indep. Business v. Sebelius","cite":"132 S. Ct. 2566","y":2012,"url":"https://www.courtlistener.com/c/S.%20Ct./132/2566/","sc":1,"by":{"0":"30"}},{"t":"case","label":"Nat’l Rev., Inc. v. Mann","cite":"140 S. Ct. 344","y":2019,"url":"https://www.courtlistener.com/c/S.%20Ct./140/344/","sc":1,"by":{"0":"26","1":"25"}},{"t":"case","label":"Nat’l-Southwire Aluminum Co. v. EPA","cite":"838 F.2d 835","y":1988,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/838/835/","by":{"0":"43"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"141 S. Ct. 1474","y":2021,"id":"2020/19-863","sc":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"37, 39"}},{"t":"case","label":"Pac. Gas & Elec. Co. v. State Energy Res. Conservation & Dev. Comm’n","cite":"461 U.S. 190","y":1983,"id":"1982/81-1945","sc":1,"sum":"The Court held that the California law did not impinge upon congressional authority. The Court found that because the rationale for enacting the law was an economic one, it did not interfere with federal regulations governing nuclear safety.","sumSrc":"Oyez","by":{"0":"27","2":"5–6, 7, 32, 40","4":"42","5":"24, 25","9":"13"}},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Tr.","cite":"136 S. Ct. 1938","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Reynolds v. United States","cite":"565 U.S. 432","y":2012,"id":"2011/10-6549","sc":1,"sum":"The Court held that under the Sex Offender Registration and Notification Act, pre-Act offenders are not obligated to register without affirmative action of the Attorney General.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Solid Waste Agency of N. Cook Cnty. v. U.S. Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"op":4,"sum":"The Court held that the provision of the CWA, which requires those discharging fill material into navigable waters to obtain a permit from the Corps, does not extend to isolated, abandoned sand and gravel pits with seasonal ponds, which provide migratory bird habitats.","sumSrc":"Oyez","by":{"0":"45","1":"16, 35","2":"36"}},{"t":"case","label":"Synar v. United States","cite":"626 F. Supp. 1374","y":1986,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./626/1374/","by":{"0":"46"}},{"t":"case","label":"Taniguchi v. Kan Pac. Saipan, Ltd.","cite":"566 U.S. 560","y":2012,"id":"2011/10-1472","sc":1,"sum":"The Court held that the winner of a federal-court lawsuit cannot be reimbursed by the losing party for any document translation costs under 28 U.S.C. § 1920(6).","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Territory of Guam v. United States","cite":"141 S. Ct. 1608","y":2021,"id":"2020/20-382","sc":1,"sum":"A settlement of environmental liabilities must resolve a specific liability under the Comprehensive Environmental Response, Compensation, and Liability Act of 1980 to give rise to a contribution action under that Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"33, 39","11":"10"}},{"t":"case","label":"Texas v. EPA","cite":"829 F.3d 405","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/829/405/","by":{"0":"27"}},{"t":"case","label":"Touby v. United States","cite":"500 U.S. 160","y":1991,"id":"1990/90-6282","sc":1,"sum":"The Court held that the Controlled Substances Act allows the Attorney General to delegate authority to the Drug Enforcement Agency.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Train v. Nat. Res. Def. Council, Inc.","cite":"421 U.S. 60","y":1975,"id":"1974/73-1742","sc":1,"op":2,"sum":"The EPA's construction of the Act permitting treatment of individual variances from state requirements as \"revisions,\" under § 110 (a) (3), of state implementation plans if they will not interfere with timely attainment and subsequent maintenance of national air quality standards, rather than as \"postponements\" under § 110 (f), was sufficiently reasonable to preclude the Court of Appeals from substituting its …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 28","3":"25, 37","7":"29"}},{"t":"case","label":"U.S. Forest Serv. v. Cowpasture River Pres. Ass’n","cite":"140 S. Ct. 1837","y":2020,"id":"2019/18-1584","sc":1,"sum":"The Court held that the U.S. Forest Service has the authority to grant rights-of-way under the Mineral Leasing Act through lands traversed by the Appalachian Trail within national forests.","sumSrc":"Oyez","by":{"0":"26, 31","1":"43","2":"33, 39","9":"13, 16","11":"8"}},{"t":"case","label":"U.S. Telecom Ass’n v. FCC","cite":"855 F.3d 381","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/855/381/","op":2,"sum":"Noting a “President's intervention [may] underscor[e] the enormous signifcance” of a regulation.","sumSrc":"opinion","by":{"0":"15, 20","1":"19, 21","2":"passim","4":"passim","6":"10","9":"14"}},{"t":"case","label":"Union Elec. Co. v. EPA","cite":"427 U.S. 246","y":1976,"id":"1975/74-1542","sc":1,"op":1,"sum":"Section 110 (a) (1) of the Clean Air Act, as added by the 1970 Amendments to the Act, requires that each State formulate, subject to approval by the Administrator of the Environmental Protection Agency (EPA), an implementation plan providing for attainment of national ambient air quality standards, both primary standards (those necessary to protect the public health) and secondary standards (those necessary to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","3":"37, 38","6":"22","7":"29"}},{"t":"case","label":"United Rentals Nw., Inc. v. Yearout Mech., Inc.","cite":"237 P.3d 728","y":2010,"court":"N.M.","url":"https://www.courtlistener.com/c/P.3d/237/728/","sum":"Explaining that “contracts for construction” describes a narrower category than “contracts relating to construction”.","sumSrc":"brief:0","by":{"0":"41"}},{"t":"case","label":"Page(s) United States v. Dist. Ct. In & For Eagle Cnty.","cite":"401 U.S. 520","y":1971,"id":"1970/87","sc":1,"op":72,"sum":"Section 666 (a) is an all-inclusive statutory provision that subjects to general adjudication in state proceedings all rights of the United States to water within a particular State's jurisdiction regardless of how they were acquired. Any conflict between adjudicated rights and reserved rights of the United States, if preserved in-the state proceeding, can ultimately be reviewed in: this Court. Pp. 522-526. 169 …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36"}},{"t":"case","label":"United States v. District of Columbia","cite":"669 F.2d 738","y":1981,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/669/738/","by":{"0":"15"}},{"t":"case","label":"United States v. Pinson","cite":"331 F.2d 759","y":1964,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/331/759/","by":{"0":"41"}},{"t":"case","label":"United States v. Raynor","cite":"302 U.S. 540","y":1938,"id":"scdb/1937-153","sc":1,"sum":"1. Section 150 of the Criminal Code provides that \"whoever shall have or retain in his control or possession after a distinctive paper has been adopted by the Secretary of the Treasury for the obligations and other securities of the United States, any similar paper adapted to the making of any such obligation or other security,. except under the authority of the Secretary of the Treasury or some other proper officer …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36"}},{"t":"case","label":"Util. Air Regul. Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"op":16,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"0":"12, 15, 17, 22, 23, 33, 39","1":"passim","2":"passim","4":"passim","6":"passim","7":"43, 47","9":"10, 19","10":"5","11":"3"}},{"t":"case","label":"West Virginia v. EPA","cite":"136 S. Ct. 1000","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1000/","sc":1,"by":{"0":"9","1":"9, 10"}},{"t":"case","label":"Whitman v. Am. Trucking Assocs.","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"op":6,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"17, 45, 46, 47","1":"19, 20, 32","2":"22, 39, 42, 43","4":"17, 30","7":"50","8":"3","9":"18"}},{"t":"case","label":"Will v. Mich. Dep’t of State Police","cite":"491 U.S. 58","y":1989,"id":"1988/87-1207","sc":1,"sum":"Neither States nor state officials acting in their official capacities are \"persons\" within meaning of § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"0":"46, 49"}},{"t":"case","label":"Zuni Pub. Sch. Dist. No. 89 v. Dep’t of Educ.","cite":"550 U.S. 81","y":2007,"id":"2006/05-1508","sc":1,"sum":"The majority concluded that \"[...] the history of the statute strongly supports the Secretary.\" No member of Congress had expressed an opinion on the formula to be used, so the Department would have been free to calculate the percentiles using either formula.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"usc","label":"15 U.S.C. § 18","url":"https://www.law.cornell.edu/uscode/text/15/18","by":{"0":"48"}},{"t":"usc","label":"15 U.S.C. § 18a","url":"https://www.law.cornell.edu/uscode/text/15/18a","by":{"0":"48"}},{"t":"usc","label":"15 U.S.C. § 717f","url":"https://www.law.cornell.edu/uscode/text/15/717f","by":{"0":"48"}},{"t":"usc","label":"15 U.S.C. § 792","url":"https://www.law.cornell.edu/uscode/text/15/792","by":{"0":"35"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"stext":{"head":"§1254. Courts of appeals; certiorari; certified questions","paras":[[0,"Cases in the courts of appeals may be reviewed by the Supreme Court by the following methods:"],[1,"(1) By writ of certiorari granted upon the petition of any party to any civil or criminal case, before or after rendition of judgment or decree;"],[1,"(2) By certification at any time by a court of appeals of any question of law in any civil or criminal case as to which instructions are desired, and upon such certification the Supreme Court may give binding instructions or require the entire record to be sent up for decision of the entire matter in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1254?type=usc&year=mostrecent&link-type=html"},"head":"§1254. Courts of appeals; certiorari; certified questions","tname":"Judiciary and Judicial Procedure","by":{"0":"2","1":"4","2":"3","3":"1"}},{"t":"usc","label":"42 U.S.C. § 7401","url":"https://www.law.cornell.edu/uscode/text/42/7401","subs":["(a)(3)"],"stext":{"head":"§7401. Congressional findings and declaration of purpose","paras":[[0,"(a) Findings"],[0,"The Congress finds—"],[1,"(1) that the predominant part of the Nation's population is located in its rapidly expanding metropolitan and other urban areas, which generally cross the boundary lines of local jurisdictions and often extend into two or more States;"],[1,"(2) that the growth in the amount and complexity of air pollution brought about by urbanization, industrial development, and the increasing use of motor vehicles, has resulted in mounting dangers to the public health and welfare, including injury to agricultural crops and livestock, damage to and the deterioration of property, and hazards to air and ground transportation;"],[1,"(3) that air pollution prevention (that is, the reduction or elimination, through any measures, of the amount of pollutants produced or created at the source) and air pollution control at its source is the primary responsibility of States and local governments; and"],[1,"(4) that Federal financial assistance and leadership is essential for the development of cooperative Federal, State, regional, and local programs to prevent and control air pollution."],[0,"(b) Declaration"],[0,"The purposes of this subchapter are—"],[1,"(1) to protect and enhance the quality of the Nation's air resources so as to promote the public health and welfare and the productive capacity of its population;"],[1,"(2) to initiate and accelerate a national research and development program to achieve the prevention and control of air pollution;"],[1,"(3) to provide technical and financial assistance to State and local governments in connection with the development and execution of their air pollution prevention and control programs; and"],[1,"(4) to encourage and assist the development and operation of regional air pollution prevention and control programs."],[0,"(c) Pollution prevention"],[0,"A primary goal of this chapter is to encourage or otherwise promote reasonable Federal, State, and local governmental actions, consistent with the provisions of this chapter, for pollution prevention."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7401?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7401. Congressional findings and declaration of purpose","tname":"The Public Health and Welfare","by":{"0":"2, 5, 28, 35, 43","3":"12","7":"2","11":"12"}},{"t":"usc","label":"42 U.S.C. § 7409","url":"https://www.law.cornell.edu/uscode/text/42/7409","subs":["(a)","(b)(1)"],"stext":{"head":"§7409. National primary and secondary ambient air quality standards","paras":[[0,"(a) Promulgation"],[0,"(1) The Administrator—"],[1,"(A) within 30 days after December 31, 1970, shall publish proposed regulations prescribing a national primary ambient air quality standard and a national secondary ambient air quality standard for each air pollutant for which air quality criteria have been issued prior to such date; and"],[1,"(B) after a reasonable time for interested persons to submit written comments thereon (but no later than 90 days after the initial publication of such proposed standards) shall by regulation promulgate such proposed national primary and secondary ambient air quality standards with such modifications as he deems appropriate."],[0,"(2) With respect to any air pollutant for which air quality criteria are issued after December 31, 1970, the Administrator shall publish, simultaneously with the issuance of such criteria and information, proposed national primary and secondary ambient air quality standards for any such pollutant. The procedure provided for in paragraph (1)(B) of this subsection shall apply to the promulgation of such standards."],[0,"(b) Protection of public health and welfare"],[0,"(1) National primary ambient air quality standards, prescribed under subsection (a) shall be ambient air quality standards the attainment and maintenance of which in the judgment of the Administrator, based on such criteria and allowing an adequate margin of safety, are requisite to protect the public health. Such primary standards may be revised in the same manner as promulgated."],[0,"(2) Any national secondary ambient air quality standard prescribed under subsection (a) shall specify a level of air quality the attainment and maintenance of which in the judgment of the Administrator, based on such criteria, is requisite to protect the public welfare from any known or anticipated adverse effects associated with the presence of such air pollutant in the ambient air. Such secondary standards may be revised in the same manner as promulgated."],[0,"(c) National primary ambient air quality standard for nitrogen dioxide"],[0,"The Administrator shall, not later than one year after August 7, 1977, promulgate a national primary ambient air quality standard for NO2 concentrations over a period of not more than 3 hours unless, based on the criteria issued under section 7408(c) of this title, he finds that there is no significant evidence that such a standard for such a period is requisite to protect public health."],[0,"(d) Review and revision of criteria and standards; independent scientific review committee; appointment; advisory functions"],[0,"(1) Not later than December 31, 1980, and at five-year intervals thereafter, the Administrator shall complete a thorough review of the criteria published under section 7408 of this title and the national ambient air quality standards promulgated under this section and shall make such revisions in such criteria and standards and promulgate such new standards as may be appropriate in accordance with section 7408 of this title and subsection (b) of this section. The Administrator may review and revise criteria or promulgate new standards earlier or more frequently than required under this paragraph."],[0,"(2)(A) The Administrator shall appoint an independent scientific review committee composed of seven members including at least one member of the National Academy of Sciences, one physician, and one person representing State air pollution control agencies."],[0,"(B) Not later than January 1, 1980, and at five-year intervals thereafter, the committee referred to in subparagraph (A) shall complete a review of the criteria published under section 7408 of this title and the national primary and secondary ambient air quality standards promulgated under this section and shall recommend to the Administrator any new national ambient air quality standards and revisions of existing criteria and standards as may be appropriate under section 7408 of this title and subsection (b) of this section."],[0,"(C) Such committee shall also (i) advise the Administrator of areas in which additional knowledge is required to appraise the adequacy and basis of existing, new, or revised national ambient air quality standards, (ii) describe the research efforts necessary to provide the required information, (iii) advise the Administrator on the relative contribution to air pollution concentrations of natural as well as anthropogenic activity, and (iv) advise the Administrator of any adverse public health, welfare, social, economic, or energy effects which may result from various strategies for attainment and maintenance of such national ambient air quality standards."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7409?type=usc&year=mostrecent&link-type=html"},"head":"§7409. National primary and secondary ambient air quality standards","tname":"The Public Health and Welfare","by":{"0":"46, 47","2":"38","6":"21","7":"29, 50","9":"18"}},{"t":"usc","label":"42 U.S.C. § 7410","url":"https://www.law.cornell.edu/uscode/text/42/7410","subs":["(a)(1)","(a)(2)(A)","(a)(2)(D)(i)(I)"],"stext":{"head":"§7410. State implementation plans for national primary and secondary ambient air quality standards","paras":[[0,"(a) Adoption of plan by State; submission to Administrator; content of plan; revision; new sources; indirect source review program; supplemental or intermittent control systems"],[0,"(1) Each State shall, after reasonable notice and public hearings, adopt and submit to the Administrator, within 3 years (or such shorter period as the Administrator may prescribe) after the promulgation of a national primary ambient air quality standard (or any revision thereof) under section 7409 of this title for any air pollutant, a plan which provides for implementation, maintenance, and enforcement of such primary standard in each air quality control region (or portion thereof) within such State. In addition, such State shall adopt and submit to the Administrator (either as a part of a plan submitted under the preceding sentence or separately) within 3 years (or such shorter period as the Administrator may prescribe) after the promulgation of a national ambient air quality secondary standard (or revision thereof), a plan which provides for implementation, maintenance, and enforcement of such secondary standard in each air quality control region (or portion thereof) within such State. Unless a separate public hearing is provided, each State shall consider its plan implementing such secondary standard at the hearing required by the first sentence of this paragraph."],[0,"(2) Each implementation plan submitted by a State under this chapter shall be adopted by the State after reasonable notice and public hearing. Each such plan shall—"],[1,"(A) include enforceable emission limitations and other control measures, means, or techniques (including economic incentives such as fees, marketable permits, and auctions of emissions rights), as well as schedules and timetables for compliance, as may be necessary or appropriate to meet the applicable requirements of this chapter;"],[1,"(B) provide for establishment and operation of appropriate devices, methods, systems, and procedures necessary to—"],[2,"(i) monitor, compile, and analyze data on ambient air quality, and"],[2,"(ii) upon request, make such data available to the Administrator;"],[1,"(C) include a program to provide for the enforcement of the measures described in subparagraph (A), and regulation of the modification and construction of any stationary source within the areas covered by the plan as necessary to assure that national ambient air quality standards are achieved, including a permit program as required in parts C and D;"],[1,"(D) contain adequate provisions—"],[2,"(i) prohibiting, consistent with the provisions of this subchapter, any source or other type of emissions activity within the State from emitting any air pollutant in amounts which will—"],[3,"(I) contribute significantly to nonattainment in, or interfere with maintenance by, any other State with respect to any such national primary or secondary ambient air quality standard, or"],[3,"(II) interfere with measures required to be included in the applicable implementation plan for any other State under part C to prevent significant deterioration of air quality or to protect visibility,"],[2,"(ii) insuring compliance with the applicable requirements of sections 7426 and 7415 of this title (relating to interstate and international pollution abatement);"],[1,"(E) provide (i) necessary assurances that the State (or, except where the Administrator deems inappropriate, the general purpose local government or governments, or a regional agency designated by the State or general purpose local governments for such purpose) will have adequate personnel, funding, and authority under State (and, as appropriate, local) law to carry out such implementation plan (and is not prohibited by any provision of Federal or State law from carrying out such implementation plan or portion thereof), (ii) requirements that the State comply with the requirements respecting State boards under section 7428 of this title, and (iii) necessary assurances that, where the State has relied on a local or regional government, agency, or instrumentality for the implementation of any plan provision, the State has responsibility for ensuring adequate implementation of such plan provision;"],[1,"(F) require, as may be prescribed by the Administrator—"],[2,"(i) the installation, maintenance, and replacement of equipment, and the implementation of other necessary steps, by owners or operators of stationary sources to monitor emissions from such sources,"],[2,"(ii) periodic reports on the nature and amounts of emissions and emissions-related data from such sources, and"],[2,"(iii) correlation of such reports by the State agency with any emission limitations or standards established pursuant to this chapter, which reports shall be available at reasonable times for public inspection;"],[1,"(G) provide for authority comparable to that in section 7603 of this title and adequate contingency plans to implement such authority;"],[1,"(H) provide for revision of such plan—"],[2,"(i) from time to time as may be necessary to take account of revisions of such national primary or secondary ambient air quality standard or the availability of improved or more expeditious methods of attaining such standard, and"],[2,"(ii) except as provided in paragraph (3)(C), whenever the Administrator finds on the basis of information available to the Administrator that the plan is substantially inadequate to attain the national ambient air quality standard which it implements or to otherwise comply with any additional requirements established under this chapter;"],[1,"(I) in the case of a plan or plan revision for an area designated as a nonattainment area, meet the applicable requirements of part D (relating to nonattainment areas);"],[1,"(J) meet the applicable requirements of section 7421 of this title (relating to consultation), section 7427 of this title (relating to public notification), and part C (relating to prevention of significant deterioration of air quality and visibility protection);"],[1,"(K) provide for—"],[2,"(i) the performance of such air quality modeling as the Administrator may prescribe for the purpose of predicting the effect on ambient air quality of any emissions of any air pollutant for which the Administrator has established a national ambient air quality standard, and"],[2,"(ii) the submission, upon request, of data related to such air quality modeling to the Administrator;"],[1,"(L) require the owner or operator of each major stationary source to pay to the permitting authority, as a condition of any permit required under this chapter, a fee sufficient to cover—"],[2,"(i) the reasonable costs of reviewing and acting upon any application for such a permit, and"],[2,"(ii) if the owner or operator receives a permit for such source, the reasonable costs of implementing and enforcing the terms and conditions of any such permit (not including any court costs or other costs associated with any enforcement action),"],[1,"until such fee requirement is superseded with respect to such sources by the Administrator's approval of a fee program under subchapter V; and"],[1,"(M) provide for consultation and participation by local political subdivisions affected by the plan."],[0,"(3)(A) Repealed. Pub. L. 101–549, title I, §101(d)(1), Nov. 15, 1990, 104 Stat. 2409."],[0,"(B) As soon as practicable, the Administrator shall, consistent with the purposes of this chapter and the Energy Supply and Environmental Coordination Act of 1974 [15 U.S.C. 791 et seq.], review each State's applicable implementation plans and report to the State on whether such plans can be revised in relation to fuel burning stationary sources (or persons supplying fuel to such sources) without interfering with the attainment and maintenance of any national ambient air quality standard within the period permitted in this section. If the Administrator determines that any such plan can be revised, he shall notify the State that a plan revision may be submitted by the State. Any plan revision which is submitted by the State shall, after public notice and opportunity for public hearing, be approved by the Administrator if the revision relates only to fuel burning stationary sources (or persons supplying fuel to such sources), and the plan as revised complies with paragraph (2) of this subsection. The Administrator shall approve or disapprove any revision no later than three months after its submission."],[0,"(C) Neither the State, in the case of a plan (or portion thereof) approved under this subsection, nor the Administrator, in the case of a plan (or portion thereof) promulgated under subsection (c), shall be required to revise an applicable implementation plan because one or more exemptions under section 7418 of this title (relating to Federal facilities), enforcement orders under section 7413(d) 1 of this title, suspensions under subsection (f) or (g) (relating to temporary energy or economic authority), orders under section 7419 of this title (relating to primary nonferrous smelters), or extensions of compliance in decrees entered under section 7413(e) 1 of this title (relating to iron- and steel-producing operations) have been granted, if such plan would have met the requirements of this section if no such exemptions, orders, or extensions had been granted."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7410?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":2,"head":"§7410. State implementation plans for national primary and secondary ambient air quality standards","tname":"The Public Health and Welfare","by":{"0":"42","3":"1, 14","7":"29, 30, 31, 37, 29, 29, 31, 37, 30","8":"15, 16","11":"15"}},{"t":"usc","label":"42 U.S.C. § 7411","url":"https://www.law.cornell.edu/uscode/text/42/7411","subs":["(a)","(d)","(a)(1)","(a)(2)","(a)(3)","(a)(5)","(a)(7)","(a)(7)(B)","(b)","(b)(1)(A)","(b)(1)(B)","(d)(1)","(d)(1)(A)","(d)(1)(A)(i)","(d)(1)(A)(ii)","(d)(2)(A)","(g)(4)(B)","(h)(1)"],"stext":{"head":"§7411. Standards of performance for new stationary sources","paras":[[0,"(a) Definitions"],[0,"For purposes of this section:"],[1,"(1) The term \"standard of performance\" means a standard for emissions of air pollutants which reflects the degree of emission limitation achievable through the application of the best system of emission reduction which (taking into account the cost of achieving such reduction and any nonair quality health and environmental impact and energy requirements) the Administrator determines has been adequately demonstrated."],[1,"(2) The term \"new source\" means any stationary source, the construction or modification of which is commenced after the publication of regulations (or, if earlier, proposed regulations) prescribing a standard of performance under this section which will be applicable to such source."],[1,"(3) The term \"stationary source\" means any building, structure, facility, or installation which emits or may emit any air pollutant. Nothing in subchapter II of this chapter relating to nonroad engines shall be construed to apply to stationary internal combustion engines."],[1,"(4) The term \"modification\" means any physical change in, or change in the method of operation of, a stationary source which increases the amount of any air pollutant emitted by such source or which results in the emission of any air pollutant not previously emitted."],[1,"(5) The term \"owner or operator\" means any person who owns, leases, operates, controls, or supervises a stationary source."],[1,"(6) The term \"existing source\" means any stationary source other than a new source."],[1,"(7) The term \"technological system of continuous emission reduction\" means—"],[2,"(A) a technological process for production or operation by any source which is inherently low-polluting or nonpolluting, or"],[2,"(B) a technological system for continuous reduction of the pollution generated by a source before such pollution is emitted into the ambient air, including precombustion cleaning or treatment of fuels."],[1,"(8) A conversion to coal (A) by reason of an order under section 2(a) of the Energy Supply and Environmental Coordination Act of 1974 [15 U.S.C. 792(a)] or any amendment thereto, or any subsequent enactment which supersedes such Act [15 U.S.C. 791 et seq.], or (B) which qualifies under section 7413(d)(5)(A)(ii) 1 of this title, shall not be deemed to be a modification for purposes of paragraphs (2) and (4) of this subsection."],[0,"(b) List of categories of stationary sources; standards of performance; information on pollution control techniques; sources owned or operated by United States; particular systems; revised standards"],[0,"(1)(A) The Administrator shall, within 90 days after December 31, 1970, publish (and from time to time thereafter shall revise) a list of categories of stationary sources. He shall include a category of sources in such list if in his judgment it causes, or contributes significantly to, air pollution which may reasonably be anticipated to endanger public health or welfare."],[0,"(B) Within one year after the inclusion of a category of stationary sources in a list under subparagraph (A), the Administrator shall publish proposed regulations, establishing Federal standards of performance for new sources within such category. The Administrator shall afford interested persons an opportunity for written comment on such proposed regulations. After considering such comments, he shall promulgate, within one year after such publication, such standards with such modifications as he deems appropriate. The Administrator shall, at least every 8 years, review and, if appropriate, revise such standards following the procedure required by this subsection for promulgation of such standards. Notwithstanding the requirements of the previous sentence, the Administrator need not review any such standard if the Administrator determines that such review is not appropriate in light of readily available information on the efficacy of such standard. Standards of performance or revisions thereof shall become effective upon promulgation. When implementation and enforcement of any requirement of this chapter indicate that emission limitations and percent reductions beyond those required by the standards promulgated under this section are achieved in practice, the Administrator shall, when revising standards promulgated under this section, consider the emission limitations and percent reductions achieved in practice."],[0,"(2) The Administrator may distinguish among classes, types, and sizes within categories of new sources for the purpose of establishing such standards."],[0,"(3) The Administrator shall, from time to time, issue information on pollution control techniques for categories of new sources and air pollutants subject to the provisions of this section."],[0,"(4) The provisions of this section shall apply to any new source owned or operated by the United States."],[0,"(5) Except as otherwise authorized under subsection (h), nothing in this section shall be construed to require, or to authorize the Administrator to require, any new or modified source to install and operate any particular technological system of continuous emission reduction to comply with any new source standard of performance."],[0,"(6) The revised standards of performance required by enactment of subsection (a)(1)(A)(i) and (ii) 1 shall be promulgated not later than one year after August 7, 1977. Any new or modified fossil fuel fired stationary source which commences construction prior to the date of publication of the proposed revised standards shall not be required to comply with such revised standards."],[0,"(c) State implementation and enforcement of standards of performance"],[0,"(1) Each State may develop and submit to the Administrator a procedure for implementing and enforcing standards of performance for new sources located in such State. If the Administrator finds the State procedure is adequate, he shall delegate to such State any authority he has under this chapter to implement and enforce such standards."],[0,"(2) Nothing in this subsection shall prohibit the Administrator from enforcing any applicable standard of performance under this section."],[0,"(d) Standards of performance for existing sources; remaining useful life of source"],[0,"(1) The Administrator shall prescribe regulations which shall establish a procedure similar to that provided by section 7410 of this title under which each State shall submit to the Administrator a plan which (A) establishes standards of performance for any existing source for any air pollutant (i) for which air quality criteria have not been issued or which is not included on a list published under section 7408(a) of this title or emitted from a source category which is regulated under section 7412 of this title but (ii) to which a standard of performance under this section would apply if such existing source were a new source, and (B) provides for the implementation and enforcement of such standards of performance. Regulations of the Administrator under this paragraph shall permit the State in applying a standard of performance to any particular source under a plan submitted under this paragraph to take into consideration, among other factors, the remaining useful life of the existing source to which such standard applies."],[0,"(2) The Administrator shall have the same authority—"],[1,"(A) to prescribe a plan for a State in cases where the State fails to submit a satisfactory plan as he would have under section 7410(c) of this title in the case of failure to submit an implementation plan, and"],[1,"(B) to enforce the provisions of such plan in cases where the State fails to enforce them as he would have under sections 7413 and 7414 of this title with respect to an implementation plan."],[0,"In promulgating a standard of performance under a plan prescribed under this paragraph, the Administrator shall take into consideration, among other factors, remaining useful lives of the sources in the category of sources to which such standard applies."],[0,"(e) Prohibited acts"],[0,"After the effective date of standards of performance promulgated under this section, it shall be unlawful for any owner or operator of any new source to operate such source in violation of any standard of performance applicable to such source."],[0,"(f) New source standards of performance"],[0,"(1) For those categories of major stationary sources that the Administrator listed under subsection (b)(1)(A) before November 15, 1990, and for which regulations had not been proposed by the Administrator by November 15, 1990, the Administrator shall—"],[1,"(A) propose regulations establishing standards of performance for at least 25 percent of such categories of sources within 2 years after November 15, 1990;"],[1,"(B) propose regulations establishing standards of performance for at least 50 percent of such categories of sources within 4 years after November 15, 1990; and"],[1,"(C) propose regulations for the remaining categories of sources within 6 years after November 15, 1990."],[0,"(2) In determining priorities for promulgating standards for categories of major stationary sources for the purpose of paragraph (1), the Administrator shall consider—"],[1,"(A) the quantity of air pollutant emissions which each such category will emit, or will be designed to emit;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7411?type=usc&year=mostrecent&link-type=html"},"op":7,"ar":1,"head":"§7411. Standards of performance for new stationary sources","tname":"The Public Health and Welfare","by":{"0":"3, 4, 5, 12, 19, 23, 28, 31, 32, 34, 37, 39, 40, 41, 47","1":"passim","2":"passim","3":"passim","4":"passim","5":"20, passim","6":"1, 21","7":"3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3","8":"passim","9":"passim","10":"passim","11":"12, 14"}},{"t":"usc","label":"42 U.S.C. § 7419","url":"https://www.law.cornell.edu/uscode/text/42/7419","by":{"0":"4"}},{"t":"usc","label":"42 U.S.C. § 7429","url":"https://www.law.cornell.edu/uscode/text/42/7429","stext":{"head":"§7429. Solid waste combustion","paras":[[0,"(a) New source performance standards"],[0,"(1) In general"],[1,"(A) The Administrator shall establish performance standards and other requirements pursuant to section 7411 of this title and this section for each category of solid waste incineration units. Such standards shall include emissions limitations and other requirements applicable to new units and guidelines (under section 7411(d) of this title and this section) and other requirements applicable to existing units."],[1,"(B) Standards under section 7411 of this title and this section applicable to solid waste incineration units with capacity greater than 250 tons per day combusting municipal waste shall be promulgated not later than 12 months after November 15, 1990. Nothing in this subparagraph shall alter any schedule for the promulgation of standards applicable to such units under section 7411 of this title pursuant to any settlement and consent decree entered by the Administrator before November 15, 1990: Provided, That, such standards are subsequently modified pursuant to the schedule established in this subparagraph to include each of the requirements of this section."],[1,"(C) Standards under section 7411 of this title and this section applicable to solid waste incineration units with capacity equal to or less than 250 tons per day combusting municipal waste and units combusting hospital waste, medical waste and infectious waste shall be promulgated not later than 24 months after November 15, 1990."],[1,"(D) Standards under section 7411 of this title and this section applicable to solid waste incineration units combusting commercial or industrial waste shall be proposed not later than 36 months after November 15, 1990, and promulgated not later than 48 months after November 15, 1990."],[1,"(E) Not later than 18 months after November 15, 1990, the Administrator shall publish a schedule for the promulgation of standards under section 7411 of this title and this section applicable to other categories of solid waste incineration units."],[0,"(2) Emissions standard"],[1,"Standards applicable to solid waste incineration units promulgated under section 7411 of this title and this section shall reflect the maximum degree of reduction in emissions of air pollutants listed under section 1 (a)(4) that the Administrator, taking into consideration the cost of achieving such emission reduction, and any non-air quality health and environmental impacts and energy requirements, determines is achievable for new or existing units in each category. The Administrator may distinguish among classes, types (including mass-burn, refuse-derived fuel, modular and other types of units), and sizes of units within a category in establishing such standards. The degree of reduction in emissions that is deemed achievable for new units in a category shall not be less stringent than the emissions control that is achieved in practice by the best controlled similar unit, as determined by the Administrator. Emissions standards for existing units in a category may be less stringent than standards for new units in the same category but shall not be less stringent than the average emissions limitation achieved by the best performing 12 percent of units in the category (excluding units which first met lowest achievable emissions rates 18 months before the date such standards are proposed or 30 months before the date such standards are promulgated, whichever is later)."],[0,"(3) Control methods and technologies"],[1,"Standards under section 7411 of this title and this section applicable to solid waste incineration units shall be based on methods and technologies for removal or destruction of pollutants before, during, or after combustion, and shall incorporate for new units siting requirements that minimize, on a site specific basis, to the maximum extent practicable, potential risks to public health or the environment."],[0,"(4) Numerical emissions limitations"],[1,"The performance standards promulgated under section 7411 of this title and this section and applicable to solid waste incineration units shall specify numerical emission limitations for the following substances or mixtures: particulate matter (total and fine), opacity (as appropriate), sulfur dioxide, hydrogen chloride, oxides of nitrogen, carbon monoxide, lead, cadmium, mercury, and dioxins and dibenzofurans. The Administrator may promulgate numerical emissions limitations or provide for the monitoring of postcombustion concentrations of surrogate substances, parameters or periods of residence time in excess of stated temperatures with respect to pollutants other than those listed in this paragraph."],[0,"(5) Review and revision"],[1,"Not later than 5 years following the initial promulgation of any performance standards and other requirements under this section and section 7411 of this title applicable to a category of solid waste incineration units, and at 5 year intervals thereafter, the Administrator shall review, and in accordance with this section and section 7411 of this title, revise such standards and requirements."],[0,"(b) Existing units"],[0,"(1) Guidelines"],[1,"Performance standards under this section and section 7411 of this title for solid waste incineration units shall include guidelines promulgated pursuant to section 7411(d) of this title and this section applicable to existing units. Such guidelines shall include, as provided in this section, each of the elements required by subsection (a) (emissions limitations, notwithstanding any restriction in section 7411(d) of this title regarding issuance of such limitations), subsection (c) (monitoring), subsection (d) (operator training), subsection (e) (permits), and subsection (h)(4) 2 (residual risk)."],[0,"(2) State plans"],[1,"Not later than 1 year after the Administrator promulgates guidelines for a category of solid waste incineration units, each State in which units in the category are operating shall submit to the Administrator a plan to implement and enforce the guidelines with respect to such units. The State plan shall be at least as protective as the guidelines promulgated by the Administrator and shall provide that each unit subject to the guidelines shall be in compliance with all requirements of this section not later than 3 years after the State plan is approved by the Administrator but not later than 5 years after the guidelines were promulgated. The Administrator shall approve or disapprove any State plan within 180 days of the submission, and if a plan is disapproved, the Administrator shall state the reasons for disapproval in writing. Any State may modify and resubmit a plan which has been disapproved by the Administrator."],[0,"(3) Federal plan"],[1,"The Administrator shall develop, implement and enforce a plan for existing solid waste incineration units within any category located in any State which has not submitted an approvable plan under this subsection with respect to units in such category within 2 years after the date on which the Administrator promulgated the relevant guidelines. Such plan shall assure that each unit subject to the plan is in compliance with all provisions of the guidelines not later than 5 years after the date the relevant guidelines are promulgated."],[0,"(c) Monitoring"],[0,"The Administrator shall, as part of each performance standard promulgated pursuant to subsection (a) and section 7411 of this title, promulgate regulations requiring the owner or operator of each solid waste incineration unit—"],[1,"(1) to monitor emissions from the unit at the point at which such emissions are emitted into the ambient air (or within the stack, combustion chamber or pollution control equipment, as appropriate) and at such other points as necessary to protect public health and the environment;"],[1,"(2) to monitor such other parameters relating to the operation of the unit and its pollution control technology as the Administrator determines are appropriate; and"],[1,"(3) to report the results of such monitoring."],[0,"Such regulations shall contain provisions regarding the frequency of monitoring, test methods and procedures validated on solid waste incineration units, and the form and frequency of reports containing the results of monitoring and shall require that any monitoring reports or test results indicating an exceedance of any standard under this section shall be reported separately and in a manner that facilitates review for purposes of enforcement actions. Such regulations shall require that copies of the results of such monitoring be maintained on file at the facility concerned and that copies shall be made available for inspection and copying by interested members of the public during business hours."],[0,"(d) Operator training"],[0,"Not later than 24 months after November 15, 1990, the Administrator shall develop and promote a model State program for the training and certification of solid waste incineration unit operators and high-capacity fossil fuel fired plant operators. The Administrator may authorize any State to implement a model program for the training of solid waste incineration unit operators and high-capacity fossil fuel fired plant operators, if the State has adopted a program which is at least as effective as the model program developed by the Administrator. Beginning on the date 36 months after the date on which performance standards and guidelines are promulgated under subsection (a) and section 7411 of this title for any category of solid waste incineration units it shall be unlawful to operate any unit in the category unless each person with control over processes affecting emissions from such unit has satisfactorily completed a training program meeting the requirements established by the Administrator under this subsection."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7429?type=usc&year=mostrecent&link-type=html"},"head":"§7429. Solid waste combustion","tname":"The Public Health and Welfare","by":{"0":"4","1":"47"}},{"t":"usc","label":"42 U.S.C. § 7475","url":"https://www.law.cornell.edu/uscode/text/42/7475","by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 7491","url":"https://www.law.cornell.edu/uscode/text/42/7491","subs":["(b)(2)(A)","(g)(2)"],"stext":{"head":"§7491. Visibility protection for Federal class I areas","paras":[[0,"(a) Impairment of visibility; list of areas; study and report"],[0,"(1) Congress hereby declares as a national goal the prevention of any future, and the remedying of any existing, impairment of visibility in mandatory class I Federal areas which impairment results from manmade air pollution."],[0,"(2) Not later than six months after August 7, 1977, the Secretary of the Interior in consultation with other Federal land managers shall review all mandatory class I Federal areas and identify those where visibility is an important value of the area. From time to time the Secretary of the Interior may revise such identifications. Not later than one year after August 7, 1977, the Administrator shall, after consultation with the Secretary of the Interior, promulgate a list of mandatory class I Federal areas in which he determines visibility is an important value."],[0,"(3) Not later than eighteen months after August 7, 1977, the Administrator shall complete a study and report to Congress on available methods for implementing the national goal set forth in paragraph (1). Such report shall include recommendations for—"],[1,"(A) methods for identifying, characterizing, determining, quantifying, and measuring visibility impairment in Federal areas referred to in paragraph (1), and"],[1,"(B) modeling techniques (or other methods) for determining the extent to which manmade air pollution may reasonably be anticipated to cause or contribute to such impairment, and"],[1,"(C) methods for preventing and remedying such manmade air pollution and resulting visibility impairment."],[0,"Such report shall also identify the classes or categories of sources and the types of air pollutants which, alone or in conjunction with other sources or pollutants, may reasonably be anticipated to cause or contribute significantly to impairment of visibility."],[0,"(4) Not later than twenty-four months after August 7, 1977, and after notice and public hearing, the Administrator shall promulgate regulations to assure (A) reasonable progress toward meeting the national goal specified in paragraph (1), and (B) compliance with the requirements of this section."],[0,"(b) Regulations"],[0,"Regulations under subsection (a)(4) shall—"],[1,"(1) provide guidelines to the States, taking into account the recommendations under subsection (a)(3) on appropriate techniques and methods for implementing this section (as provided in subparagraphs (A) through (C) of such subsection (a)(3)), and"],[1,"(2) require each applicable implementation plan for a State in which any area listed by the Administrator under subsection (a)(2) is located (or for a State the emissions from which may reasonably be anticipated to cause or contribute to any impairment of visibility in any such area) to contain such emission limits, schedules of compliance and other measures as may be necessary to make reasonable progress toward meeting the national goal specified in subsection (a), including—"],[2,"(A) except as otherwise provided pursuant to subsection (c), a requirement that each major stationary source which is in existence on August 7, 1977, but which has not been in operation for more than fifteen years as of such date, and which, as determined by the State (or the Administrator in the case of a plan promulgated under section 7410(c) of this title) emits any air pollutant which may reasonably be anticipated to cause or contribute to any impairment of visibility in any such area, shall procure, install, and operate, as expeditiously as practicable (and maintain thereafter) the best available retrofit technology, as determined by the State (or the Administrator in the case of a plan promulgated under section 7410(c) of this title) for controlling emissions from such source for the purpose of eliminating or reducing any such impairment, and"],[2,"(B) a long-term (ten to fifteen years) strategy for making reasonable progress toward meeting the national goal specified in subsection (a)."],[0,"In the case of a fossil-fuel fired generating powerplant having a total generating capacity in excess of 750 megawatts, the emission limitations required under this paragraph shall be determined pursuant to guidelines, promulgated by the Administrator under paragraph (1)."],[0,"(c) Exemptions"],[0,"(1) The Administrator may, by rule, after notice and opportunity for public hearing, exempt any major stationary source from the requirement of subsection (b)(2)(A), upon his determination that such source does not or will not, by itself or in combination with other sources, emit any air pollutant which may reasonably be anticipated to cause or contribute to a significant impairment of visibility in any mandatory class I Federal area."],[0,"(2) Paragraph (1) of this subsection shall not be applicable to any fossil-fuel fired powerplant with total design capacity of 750 megawatts or more, unless the owner or operator of any such plant demonstrates to the satisfaction of the Administrator that such powerplant is located at such distance from all areas listed by the Administrator under subsection (a)(2) that such powerplant does not or will not, by itself or in combination with other sources, emit any air pollutant which may reasonably be anticipated to cause or contribute to significant impairment of visibility in any such area."],[0,"(3) An exemption under this subsection shall be effective only upon concurrence by the appropriate Federal land manager or managers with the Administrator's determination under this subsection."],[0,"(d) Consultations with appropriate Federal land managers"],[0,"Before holding the public hearing on the proposed revision of an applicable implementation plan to meet the requirements of this section, the State (or the Administrator, in the case of a plan promulgated under section 7410(c) of this title) shall consult in person with the appropriate Federal land manager or managers and shall include a summary of the conclusions and recommendations of the Federal land managers in the notice to the public."],[0,"(e) Buffer zones"],[0,"In promulgating regulations under this section, the Administrator shall not require the use of any automatic or uniform buffer zone or zones."],[0,"(f) Nondiscretionary duty"],[0,"For purposes of section 7604(a)(2) of this title, the meeting of the national goal specified in subsection (a)(1) by any specific date or dates shall not be considered a \"nondiscretionary duty\" of the Administrator."],[0,"(g) Definitions"],[0,"For the purpose of this section—"],[1,"(1) in determining reasonable progress there shall be taken into consideration the costs of compliance, the time necessary for compliance, and the energy and nonair quality environmental impacts of compliance, and the remaining useful life of any existing source subject to such requirements;"],[1,"(2) in determining best available retrofit technology the State (or the Administrator in determining emission limitations which reflect such technology) shall take into consideration the costs of compliance, the energy and nonair quality environmental impacts of compliance, any existing pollution control technology in use at the source, the remaining useful life of the source, and the degree of improvement in visibility which may reasonably be anticipated to result from the use of such technology;"],[1,"(3) the term \"manmade air pollution\" means air pollution which results directly or indirectly from human activities;"],[1,"(4) the term \"as expeditiously as practicable\" means as expeditiously as practicable but in no event later than five years after the date of approval of a plan revision under this section (or the date of promulgation of such a plan revision in the case of action by the Administrator under section 7410(c) of this title for purposes of this section);"],[1,"(5) the term \"mandatory class I Federal areas\" means Federal areas which may not be designated as other than class I under this part;"],[1,"(6) the terms \"visibility impairment\" and \"impairment of visibility\" shall include reduction in visual range and atmospheric discoloration; and"],[1,"(7) the term \"major stationary source\" means the following types of stationary sources with the potential to emit 250 tons or more of any pollutant: fossil-fuel fired steam electric plants of more than 250 million British thermal units per hour heat input, coal cleaning plants (thermal dryers), kraft pulp mills, Portland Cement plants, primary zinc smelters, iron and steel mill plants, primary aluminum ore reduction plants, primary copper smelters, municipal incinerators capable of charging more than 250 tons of refuse per day, hydrofluoric, sulfuric, and nitric acid plants, petroleum refineries, lime plants, phosphate rock processing plants, coke oven batteries, sulfur recovery plants, carbon black plants (furnace process), primary lead smelters, fuel conversion plants, sintering plants, secondary metal production facilities, chemical process plants, fossil-fuel boilers of more than 250 million British thermal units per hour heat input, petroleum storage and transfer facilities with a capacity exceeding 300,000 barrels, taconite ore processing facilities, glass fiber processing plants, charcoal production facilities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7491?type=usc&year=mostrecent&link-type=html"},"head":"§7491. Visibility protection for Federal class I areas","tname":"The Public Health and Welfare","by":{"0":"43","7":"33, 33"}},{"t":"usc","label":"42 U.S.C. § 7503","url":"https://www.law.cornell.edu/uscode/text/42/7503","by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 7545","url":"https://www.law.cornell.edu/uscode/text/42/7545","by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 7602","url":"https://www.law.cornell.edu/uscode/text/42/7602","subs":["(k)"],"stext":{"head":"§7602. Definitions","paras":[[0,"When used in this chapter—"],[0,"(a) The term \"Administrator\" means the Administrator of the Environmental Protection Agency."],[0,"(b) The term \"air pollution control agency\" means any of the following:"],[1,"(1) A single State agency designated by the Governor of that State as the official State air pollution control agency for purposes of this chapter."],[1,"(2) An agency established by two or more States and having substantial powers or duties pertaining to the prevention and control of air pollution."],[1,"(3) A city, county, or other local government health authority, or, in the case of any city, county, or other local government in which there is an agency other than the health authority charged with responsibility for enforcing ordinances or laws relating to the prevention and control of air pollution, such other agency."],[1,"(4) An agency of two or more municipalities located in the same State or in different States and having substantial powers or duties pertaining to the prevention and control of air pollution."],[1,"(5) An agency of an Indian tribe."],[0,"(c) The term \"interstate air pollution control agency\" means—"],[1,"(1) an air pollution control agency established by two or more States, or"],[1,"(2) an air pollution control agency of two or more municipalities located in different States."],[0,"(d) The term \"State\" means a State, the District of Columbia, the Commonwealth of Puerto Rico, the Virgin Islands, Guam, and American Samoa and includes the Commonwealth of the Northern Mariana Islands."],[0,"(e) The term \"person\" includes an individual, corporation, partnership, association, State, municipality, political subdivision of a State, and any agency, department, or instrumentality of the United States and any officer, agent, or employee thereof."],[0,"(f) The term \"municipality\" means a city, town, borough, county, parish, district, or other public body created by or pursuant to State law."],[0,"(g) The term \"air pollutant\" means any air pollution agent or combination of such agents, including any physical, chemical, biological, radioactive (including source material, special nuclear material, and byproduct material) substance or matter which is emitted into or otherwise enters the ambient air. Such term includes any precursors to the formation of any air pollutant, to the extent the Administrator has identified such precursor or precursors for the particular purpose for which the term \"air pollutant\" is used."],[0,"(h) All language referring to effects on welfare includes, but is not limited to, effects on soils, water, crops, vegetation, manmade materials, animals, wildlife, weather, visibility, and climate, damage to and deterioration of property, and hazards to transportation, as well as effects on economic values and on personal comfort and well-being, whether caused by transformation, conversion, or combination with other air pollutants."],[0,"(i) The term \"Federal land manager\" means, with respect to any lands in the United States, the Secretary of the department with authority over such lands."],[0,"(j) Except as otherwise expressly provided, the terms \"major stationary source\" and \"major emitting facility\" mean any stationary facility or source of air pollutants which directly emits, or has the potential to emit, one hundred tons per year or more of any air pollutant (including any major emitting facility or source of fugitive emissions of any such pollutant, as determined by rule by the Administrator)."],[0,"(k) The terms \"emission limitation\" and \"emission standard\" mean a requirement established by the State or the Administrator which limits the quantity, rate, or concentration of emissions of air pollutants on a continuous basis, including any requirement relating to the operation or maintenance of a source to assure continuous emission reduction, and any design, equipment, work practice or operational standard promulgated under this chapter..1"],[0,"(l) The term \"standard of performance\" means a requirement of continuous emission reduction, including any requirement relating to the operation or maintenance of a source to assure continuous emission reduction."],[0,"(m) The term \"means of emission limitation\" means a system of continuous emission reduction (including the use of specific technology or fuels with specified pollution characteristics)."],[0,"(n) The term \"primary standard attainment date\" means the date specified in the applicable implementation plan for the attainment of a national primary ambient air quality standard for any air pollutant."],[0,"(o) The term \"delayed compliance order\" means an order issued by the State or by the Administrator to an existing stationary source, postponing the date required under an applicable implementation plan for compliance by such source with any requirement of such plan."],[0,"(p) The term \"schedule and timetable of compliance\" means a schedule of required measures including an enforceable sequence of actions or operations leading to compliance with an emission limitation, other limitation, prohibition, or standard."],[0,"(q) For purposes of this chapter, the term \"applicable implementation plan\" means the portion (or portions) of the implementation plan, or most recent revision thereof, which has been approved under section 7410 of this title, or promulgated under section 7410(c) of this title, or promulgated or approved pursuant to regulations promulgated under section 7601(d) of this title and which implements the relevant requirements of this chapter."],[0,"(r) Indian Tribe.—The term \"Indian tribe\" means any Indian tribe, band, nation, or other organized group or community, including any Alaska Native village, which is Federally recognized as eligible for the special programs and services provided by the United States to Indians because of their status as Indians."],[0,"(s) VOC.—The term \"VOC\" means volatile organic compound, as defined by the Administrator."],[0,"(t) PM–10.—The term \"PM–10\" means particulate matter with an aerodynamic diameter less than or equal to a nominal ten micrometers, as measured by such method as the Administrator may determine."],[0,"(u) NAAQS and CTG.—The term \"NAAQS\" means national ambient air quality standard. The term \"CTG\" means a Control Technique Guideline published by the Administrator under section 7408 of this title."],[0,"(v) NOx.—The term \"NOx\" means oxides of nitrogen."],[0,"(w) CO.—The term \"CO\" means carbon monoxide."],[0,"(x) Small Source.—The term \"small source\" means a source that emits less than 100 tons of regulated pollutants per year, or any class of persons that the Administrator determines, through regulation, generally lack technical ability or knowledge regarding control of air pollution."],[0,"(y) Federal Implementation Plan.—The term \"Federal implementation plan\" means a plan (or portion thereof) promulgated by the Administrator to fill all or a portion of a gap or otherwise correct all or a portion of an inadequacy in a State implementation plan, and which includes enforceable emission limitations or other control measures, means or techniques (including economic incentives, such as marketable permits or auctions of emissions allowances), and provides for attainment of the relevant national ambient air quality standard."],[0,"(z) Stationary Source.—The term \"stationary source\" means generally any source of an air pollutant except those emissions resulting directly from an internal combustion engine for transportation purposes or from a nonroad engine or nonroad vehicle as defined in section 7550 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7602?type=usc&year=mostrecent&link-type=html"},"head":"§7602. Definitions","tname":"The Public Health and Welfare","by":{"0":"2, 34","2":"8, 36","3":"2, passim"}},{"t":"usc","label":"42 U.S.C. § 7651","url":"https://www.law.cornell.edu/uscode/text/42/7651","subs":["(b)"],"stext":{"head":"§7651. Findings and purposes","paras":[[0,"(a) Findings"],[0,"The Congress finds that—"],[1,"(1) the presence of acidic compounds and their precursors in the atmosphere and in deposition from the atmosphere represents a threat to natural resources, ecosystems, materials, visibility, and public health;"],[1,"(2) the principal sources of the acidic compounds and their precursors in the atmosphere are emissions of sulfur and nitrogen oxides from the combustion of fossil fuels;"],[1,"(3) the problem of acid deposition is of national and international significance;"],[1,"(4) strategies and technologies for the control of precursors to acid deposition exist now that are economically feasible, and improved methods are expected to become increasingly available over the next decade;"],[1,"(5) current and future generations of Americans will be adversely affected by delaying measures to remedy the problem;"],[1,"(6) reduction of total atmospheric loading of sulfur dioxide and nitrogen oxides will enhance protection of the public health and welfare and the environment; and"],[1,"(7) control measures to reduce precursor emissions from steam-electric generating units should be initiated without delay."],[0,"(b) Purposes"],[0,"The purpose of this subchapter is to reduce the adverse effects of acid deposition through reductions in annual emissions of sulfur dioxide of ten million tons from 1980 emission levels, and, in combination with other provisions of this chapter, of nitrogen oxides emissions of approximately two million tons from 1980 emission levels, in the forty-eight contiguous States and the District of Columbia. It is the intent of this subchapter to effectuate such reductions by requiring compliance by affected sources with prescribed emission limitations by specified deadlines, which limitations may be met through alternative methods of compliance provided by an emission allocation and transfer system. It is also the purpose of this subchapter to encourage energy conservation, use of renewable and clean alternative technologies, and pollution prevention as a long-range strategy, consistent with the provisions of this subchapter, for reducing air pollution and other adverse impacts of energy production and use."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7651?type=usc&year=mostrecent&link-type=html"},"head":"§7651. Findings and purposes","tname":"The Public Health and Welfare","by":{"0":"3, 42","2":"39","4":"46, 47","7":"31"}},{"t":"usc","label":"42 U.S.C. § 7651f","url":"https://www.law.cornell.edu/uscode/text/42/7651f","subs":["(b)(2)"],"stext":{"head":"§7651f. Nitrogen oxides emission reduction program","paras":[[0,"(a) Applicability"],[0,"On the date that a coal-fired utility unit becomes an affected unit pursuant to sections 7651c, 7651d,1 7651h of this title, or on the date a unit subject to the provisions of section 7651c(d) or 7651h(b) of this title, must meet the SO2 reduction requirements, each such unit shall become an affected unit for purposes of this section and shall be subject to the emission limitations for nitrogen oxides set forth herein."],[0,"(b) Emission limitations"],[0,"(1) Not later than eighteen months after November 15, 1990, the Administrator shall by regulation establish annual allowable emission limitations for nitrogen oxides for the types of utility boilers listed below, which limitations shall not exceed the rates listed below: Provided, That the Administrator may set a rate higher than that listed for any type of utility boiler if the Administrator finds that the maximum listed rate for that boiler type cannot be achieved using low NOx burner technology. The maximum allowable emission rates are as follows:"],[1,"(A) for tangentially fired boilers, 0.45 lb/mmBtu;"],[1,"(B) for dry bottom wall-fired boilers (other than units applying cell burner technology), 0.50 lb/mmBtu."],[0,"After January 1, 1995, it shall be unlawful for any unit that is an affected unit on that date and is of the type listed in this paragraph to emit nitrogen oxides in excess of the emission rates set by the Administrator pursuant to this paragraph."],[0,"(2) Not later than January 1, 1997, the Administrator shall, by regulation, establish allowable emission limitations on a lb/mmBtu, annual average basis, for nitrogen oxides for the following types of utility boilers:"],[1,"(A) wet bottom wall-fired boilers;"],[1,"(B) cyclones;"],[1,"(C) units applying cell burner technology;"],[1,"(D) all other types of utility boilers."],[0,"The Administrator shall base such rates on the degree of reduction achievable through the retrofit application of the best system of continuous emission reduction, taking into account available technology, costs and energy and environmental impacts; and which is comparable to the costs of nitrogen oxides controls set pursuant to subsection (b)(1). Not later than January 1, 1997, the Administrator may revise the applicable emission limitations for tangentially fired and dry bottom, wall-fired boilers (other than cell burners) to be more stringent if the Administrator determines that more effective low NOx burner technology is available: Provided, That, no unit that is an affected unit pursuant to section 7651c of this title and that is subject to the requirements of subsection (b)(1), shall be subject to the revised emission limitations, if any."],[0,"(c) Revised performance standards"],[0,"(1) 2 Not later than January 1, 1993, the Administrator shall propose revised standards of performance to section 7411 of this title for nitrogen oxides emissions from fossil-fuel fired steam generating units, including both electric utility and nonutility units. Not later than January 1, 1994, the Administrator shall promulgate such revised standards of performance. Such revised standards of performance shall reflect improvements in methods for the reduction of emissions of oxides of nitrogen."],[0,"(d) Alternative emission limitations"],[0,"The permitting authority shall, upon request of an owner or operator of a unit subject to this section, authorize an emission limitation less stringent than the applicable limitation established under subsection (b)(1) or (b)(2) upon a determination that—"],[1,"(1) a unit subject to subsection (b)(1) cannot meet the applicable limitation using low NOx burner technology; or"],[1,"(2) a unit subject to subsection (b)(2) cannot meet the applicable rate using the technology on which the Administrator based the applicable emission limitation."],[0,"The permitting authority shall base such determination upon a showing satisfactory to the permitting authority, in accordance with regulations established by the Administrator not later than eighteen months after November 15, 1990, that the owner or operator—"],[1,"(1) has properly installed appropriate control equipment designed to meet the applicable emission rate;"],[1,"(2) has properly operated such equipment for a period of fifteen months (or such other period of time as the Administrator determines through the regulations), and provides operating and monitoring data for such period demonstrating that the unit cannot meet the applicable emission rate; and"],[1,"(3) has specified an emission rate that such unit can meet on an annual average basis."],[0,"The permitting authority shall issue an operating permit for the unit in question, in accordance with section 7651g of this title and part B 3 of title III—"],[1,"(i) that permits the unit during the demonstration period referred to in subparagraph (2) above, to emit at a rate in excess of the applicable emission rate;"],[1,"(ii) at the conclusion of the demonstration period to revise the operating permit to reflect the alternative emission rate demonstrated in paragraphs (2) and (3) above."],[0,"Units subject to subsection (b)(1) for which an alternative emission limitation is established shall not be required to install any additional control technology beyond low NOx burners. Nothing in this section shall preclude an owner or operator from installing and operating an alternative NOx control technology capable of achieving the applicable emission limitation. If the owner or operator of a unit subject to the emissions limitation requirements of subsection (b)(1) demonstrates to the satisfaction of the Administrator that the technology necessary to meet such requirements is not in adequate supply to enable its installation and operation at the unit, consistent with system reliability, by January 1, 1995, then the Administrator shall extend the deadline for compliance for the unit by a period of 15 months. Any owner or operator may petition the Administrator to make a determination under the previous sentence. The Administrator shall grant or deny such petition within 3 months of submittal."],[0,"(e) Emissions averaging"],[0,"In lieu of complying with the applicable emission limitations under subsection (b)(1), (2), or (d), the owner or operator of two or more units subject to one or more of the applicable emission limitations set pursuant to these sections,4 may petition the permitting authority for alternative contemporaneous annual emission limitations for such units that ensure that (1) the actual annual emission rate in pounds of nitrogen oxides per million Btu averaged over the units in question is a rate that is less than or equal to (2) the Btu-weighted average annual emission rate for the same units if they had been operated, during the same period of time, in compliance with limitations set in accordance with the applicable emission rates set pursuant to subsections (b)(1) and (2)."],[0,"If the permitting authority determines, in accordance with regulations issued by the Administrator not later than eighteen months after November 15, 1990; 5 that the conditions in the paragraph above can be met, the permitting authority shall issue operating permits for such units, in accordance with section 7651g of this title and part B 3 of title III, that allow alternative contemporaneous annual emission limitations. Such emission limitations shall only remain in effect while both units continue operation under the conditions specified in their respective operating permits."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7651f?type=usc&year=mostrecent&link-type=html"},"head":"§7651f. Nitrogen oxides emission reduction program","tname":"The Public Health and Welfare","by":{"0":"43","1":"29","7":"32"}},{"t":"usc","label":"42 U.S.C. § 7671d","url":"https://www.law.cornell.edu/uscode/text/42/7671d","by":{"0":"3, 42"}},{"t":"reg","label":"40 C.F.R. § 60.21","url":"https://www.ecfr.gov/current/title-40/section-60.21","by":{"0":"22"}},{"t":"reg","label":"40 C.F.R. § 60.5745","url":"https://www.ecfr.gov/current/title-40/section-60.5745","by":{"0":"30"}},{"t":"reg","label":"40 C.F.R. § 60.5780","url":"https://www.ecfr.gov/current/title-40/section-60.5780","by":{"0":"30"}},{"t":"reg","label":"40 Fed. Reg. 53,340","url":"https://www.govinfo.gov/link/fr/40/53340","by":{"0":"5, 6, 8","1":"41"}},{"t":"reg","label":"60 Fed. Reg. 65,387","url":"https://www.govinfo.gov/link/fr/60/65387","by":{"0":"6, 22","1":"47","4":"5, 40"}},{"t":"reg","label":"61 Fed. Reg. 9,905","url":"https://www.govinfo.gov/link/fr/61/9905","by":{"0":"22","1":"45","2":"9","4":"5, 40"}},{"t":"reg","label":"70 Fed. Reg. 28,606","url":"https://www.govinfo.gov/link/fr/70/28606","by":{"0":"6, 22","1":"45, 47, 48","4":"6, 40","7":"38","9":"7"}},{"t":"reg","label":"79 Fed. Reg. 34,830","url":"https://www.govinfo.gov/link/fr/79/34830","by":{"0":"6","2":"11"}},{"t":"reg","label":"80 Fed. Reg. 64,510","url":"https://www.govinfo.gov/link/fr/80/64510","by":{"0":"8","1":"6, 7, 46","6":"23","7":"5"}},{"t":"law","label":"Pub. L. No. 116-94","url":"https://www.govinfo.gov/link/plaw/116/public/94","by":{"0":"25"}},{"t":"case","label":"Crowell v. Benson","cite":"285 U.S. 22","y":1932,"id":"scdb/1931-083","sc":1,"sum":"(1) As the claims are governed by the maritime law and within the admiralty jurisdiction, trial by jury is not required by the Seventh Amendment. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20, 21"}},{"t":"case","label":"Dep’t of Com. v. New York","cite":"139 S. Ct. 2551","y":2019,"id":"2018/18-966","sc":1,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"30"}},{"t":"case","label":"Indianapolis Power & Light Co. v. EPA","cite":"58 F.3d 643","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/58/643/","by":{"1":"42"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Maryland v. King","cite":"567 U.S. 1301","y":2012,"url":"https://supreme.justia.com/cases/federal/us/567/1301/","sc":1,"by":{"1":"10"}},{"t":"case","label":"Medellín v. Texas","cite":"552 U.S. 491","y":2008,"id":"2007/06-984","sc":1,"sum":"The Court held that the signed Protocol of the Vienna Convention did not make the treaty self-executing and, therefore, the treaty is not binding upon state courts until it is enacted into law by Congress.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"op":3,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"1":"20","4":"22"}},{"t":"case","label":"New Jersey v. EPA","cite":"517 F.3d 574","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/517/574/","op":1,"ar":1,"sum":"Describing guidelines as “based on maximum achievable control technology” and noting they will require plants to “purchase and install ... equipment”.","sumSrc":"brief:1","by":{"1":"47, 48","4":"6, 41","7":"38","9":"7"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"op":13,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Paul v. United States","cite":"140 S. Ct. 342","y":2019,"url":"https://www.courtlistener.com/c/S.%20Ct./140/342/","sc":1,"op":1,"by":{"1":"20","4":"passim"}},{"t":"case","label":"Romag Fasteners, Inc. v. Fossil, Inc.","cite":"140 S. Ct. 1492","y":2020,"id":"2019/18-1233","sc":1,"sum":"The Court held that under Section 35 of the Lanham Act, a plaintiff does not need to show willful infringement to receive an award of an infringer’s profits for a violation of Section 43(a).","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Textron Lycoming Reciprocating Engine Div., Avco Corp. v. Auto. Workers","cite":"523 U.S. 653","y":1998,"id":"1997/97-463","sc":1,"sum":"The Court held that neither it nor the lower federal courts have subject-matter jurisdiction under section 301 because the Union's complaint alleged no violation of the collective-bargaining agreement. \"Suits for violation of contracts\" under [section 301(a)] are not suits that claim a contract is invalid, but suits that claim a contract has been violated, wrote Justice Scalia.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Weyerhaeuser Co. v. U.S. Fish & Wildlife Serv.","cite":"139 S. Ct. 361","y":2018,"id":"2018/17-71","sc":1,"sum":"An area is eligible for designation as “critical habitat” under the Endangered Species Act of 1973 only if it is habitat for the listed species; and the Secretary of the Interior’s decision not to exclude an area from critical habitat under 16 U. S. C. §1533(b)(2) is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"38"}},{"t":"const","label":"Article I","by":{"1":"20"}},{"t":"usc","label":"26 U.S.C. § 36B","url":"https://www.law.cornell.edu/uscode/text/26/36B","by":{"1":"28"}},{"t":"usc","label":"42 U.S.C. § 264","url":"https://www.law.cornell.edu/uscode/text/42/264","by":{"1":"18"}},{"t":"usc","label":"42 U.S.C. § 7607","url":"https://www.law.cornell.edu/uscode/text/42/7607","subs":["(b)(1)","(d)(5)"],"stext":{"head":"§7607. Administrative proceedings and judicial review","paras":[[0,"(a) Administrative subpenas; confidentiality; witnesses"],[0,"In connection with any determination under section 7410(f) of this title, or for purposes of obtaining information under section 7521(b)(4) 1 or 7545(c)(3) of this title, any investigation, monitoring, reporting requirement, entry, compliance inspection, or administrative enforcement proceeding under the 2 chapter (including but not limited to section 7413, section 7414, section 7420, section 7429, section 7477, section 7524, section 7525, section 7542, section 7603, or section 7606 of this title),,3 the Administrator may issue subpenas for the attendance and testimony of witnesses and the production of relevant papers, books, and documents, and he may administer oaths. Except for emission data, upon a showing satisfactory to the Administrator by such owner or operator that such papers, books, documents, or information or particular part thereof, if made public, would divulge trade secrets or secret processes of such owner or operator, the Administrator shall consider such record, report, or information or particular portion thereof confidential in accordance with the purposes of section 1905 of title 18, except that such paper, book, document, or information may be disclosed to other officers, employees, or authorized representatives of the United States concerned with carrying out this chapter, to persons carrying out the National Academy of Sciences' study and investigation provided for in section 7521(c) of this title, or when relevant in any proceeding under this chapter. Witnesses summoned shall be paid the same fees and mileage that are paid witnesses in the courts of the United States. In case of contumacy or refusal to obey a subpena served upon any person under this subparagraph,4 the district court of the United States for any district in which such person is found or resides or transacts business, upon application by the United States and after notice to such person, shall have jurisdiction to issue an order requiring such person to appear and give testimony before the Administrator to appear and produce papers, books, and documents before the Administrator, or both, and any failure to obey such order of the court may be punished by such court as a contempt thereof."],[0,"(b) Judicial review"],[0,"(1) A petition for review of action of the Administrator in promulgating any national primary or secondary ambient air quality standard, any emission standard or requirement under section 7412 of this title, any standard of performance or requirement under section 7411 of this title,,3 any standard under section 7521 of this title (other than a standard required to be prescribed under section 7521(b)(1) of this title), any determination under section 7521(b)(5) 1 of this title, any control or prohibition under section 7545 of this title, any standard under section 7571 of this title, any rule issued under section 7413, 7419, or under section 7420 of this title, or any other nationally applicable regulations promulgated, or final action taken, by the Administrator under this chapter may be filed only in the United States Court of Appeals for the District of Columbia. A petition for review of the Administrator's action in approving or promulgating any implementation plan under section 7410 of this title or section 7411(d) of this title, any order under section 7411(j) of this title, under section 7412 of this title, under section 7419 of this title, or under section 7420 of this title, or his action under section 1857c–10(c)(2)(A), (B), or (C) of this title (as in effect before August 7, 1977) or under regulations thereunder, or revising regulations for enhanced monitoring and compliance certification programs under section 7414(a)(3) of this title, or any other final action of the Administrator under this chapter (including any denial or disapproval by the Administrator under subchapter I) which is locally or regionally applicable may be filed only in the United States Court of Appeals for the appropriate circuit. Notwithstanding the preceding sentence a petition for review of any action referred to in such sentence may be filed only in the United States Court of Appeals for the District of Columbia if such action is based on a determination of nationwide scope or effect and if in taking such action the Administrator finds and publishes that such action is based on such a determination. Any petition for review under this subsection shall be filed within sixty days from the date notice of such promulgation, approval, or action appears in the Federal Register, except that if such petition is based solely on grounds arising after such sixtieth day, then any petition for review under this subsection shall be filed within sixty days after such grounds arise. The filing of a petition for reconsideration by the Administrator of any otherwise final rule or action shall not affect the finality of such rule or action for purposes of judicial review nor extend the time within which a petition for judicial review of such rule or action under this section may be filed, and shall not postpone the effectiveness of such rule or action."],[0,"(2) Action of the Administrator with respect to which review could have been obtained under paragraph (1) shall not be subject to judicial review in civil or criminal proceedings for enforcement. Where a final decision by the Administrator defers performance of any nondiscretionary statutory action to a later time, any person may challenge the deferral pursuant to paragraph (1)."],[0,"(c) Additional evidence"],[0,"In any judicial proceeding in which review is sought of a determination under this chapter required to be made on the record after notice and opportunity for hearing, if any party applies to the court for leave to adduce additional evidence, and shows to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the proceeding before the Administrator, the court may order such additional evidence (and evidence in rebuttal thereof) to be taken before the Administrator, in such manner and upon such terms and conditions as to 5 the court may deem proper. The Administrator may modify his findings as to the facts, or make new findings, by reason of the additional evidence so taken and he shall file such modified or new findings, and his recommendation, if any, for the modification or setting aside of his original determination, with the return of such additional evidence."],[0,"(d) Rulemaking"],[0,"(1) This subsection applies to—"],[1,"(A) the promulgation or revision of any national ambient air quality standard under section 7409 of this title,"],[1,"(B) the promulgation or revision of an implementation plan by the Administrator under section 7410(c) of this title,"],[1,"(C) the promulgation or revision of any standard of performance under section 7411 of this title, or emission standard or limitation under section 7412(d) of this title, any standard under section 7412(f) of this title, or any regulation under section 7412(g)(1)(D) and (F) 6 of this title, or any regulation under section 7412(m) or (n) of this title,"],[1,"(D) the promulgation of any requirement for solid waste combustion under section 7429 of this title,"],[1,"(E) the promulgation or revision of any regulation pertaining to any fuel or fuel additive under section 7545 of this title,"],[1,"(F) the promulgation or revision of any aircraft emission standard under section 7571 of this title,"],[1,"(G) the promulgation or revision of any regulation under subchapter IV–A (relating to control of acid deposition),"],[1,"(H) promulgation or revision of regulations pertaining to primary nonferrous smelter orders under section 7419 of this title (but not including the granting or denying of any such order),"],[1,"(I) promulgation or revision of regulations under subchapter VI (relating to stratosphere and ozone protection),"],[1,"(J) promulgation or revision of regulations under part C of subchapter I (relating to prevention of significant deterioration of air quality and protection of visibility),"],[1,"(K) promulgation or revision of regulations under section 7521 of this title and test procedures for new motor vehicles or engines under section 7525 of this title, and the revision of a standard under section 7521(a)(3) of this title,"],[1,"(L) promulgation or revision of regulations for noncompliance penalties under section 7420 of this title,"],[1,"(M) promulgation or revision of any regulations promulgated under section 7541 of this title (relating to warranties and compliance by vehicles in actual use),"],[1,"(N) action of the Administrator under section 7426 of this title (relating to interstate pollution abatement),"],[1,"(O) the promulgation or revision of any regulation pertaining to consumer and commercial products under section 7511b(e) of this title,"],[1,"(P) the promulgation or revision of any regulation pertaining to field citations under section 7413(d)(3) of this title,"],[1,"(Q) the promulgation or revision of any regulation pertaining to urban buses or the clean-fuel vehicle, clean-fuel fleet, and clean fuel programs under part C of subchapter II,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7607?type=usc&year=mostrecent&link-type=html"},"head":"§7607. Administrative proceedings and judicial review","tname":"The Public Health and Welfare","by":{"1":"9","7":"21, 20","10":"13"}},{"t":"usc","label":"42 U.S.C. § 7651-7651o","url":"https://www.law.cornell.edu/uscode/text/42/7651-7651o","by":{"1":"42","6":"22"}},{"t":"usc","label":"42 U.S.C. § 7671-7671q","url":"https://www.law.cornell.edu/uscode/text/42/7671-7671q","by":{"1":"42","6":"22"}},{"t":"reg","label":"40 C.F.R. § 60.22","url":"https://www.ecfr.gov/current/title-40/section-60.22","by":{"1":"5, 31","2":"9"}},{"t":"reg","label":"Emission Guideline for Sulfuric Acid Mist, 42 Fed. Reg. 55,796","url":"https://www.govinfo.gov/link/fr/42/55796","by":{"1":"45","4":"5, 40"}},{"t":"reg","label":"Endangerment and Cause or Contribute Findings for Greenhouse Gases Under Section 202(a) of the Clean Air Act, 74 Fed. Reg. 66,496","url":"https://www.govinfo.gov/link/fr/74/66496","by":{"1":"6"}},{"t":"reg","label":"Kraft Pulp Mills; Final Guideline Document; Availability, 44 Fed. Reg. 29,828","url":"https://www.govinfo.gov/link/fr/44/29828","by":{"1":"45","4":"5, 40"}},{"t":"reg","label":"Phosphate Fertilizer Plants, Final Guideline Document Availability, 42 Fed. Reg. 12,022","url":"https://www.govinfo.gov/link/fr/42/12022","by":{"1":"44","4":"5, 40"}},{"t":"reg","label":"Primary Aluminum Plants; Availability of Final Guideline Document, 45 Fed. Reg. 26,294","url":"https://www.govinfo.gov/link/fr/45/26294","by":{"1":"45","4":"5, 40"}},{"t":"case","label":"Astoria Fed. Savings & Loan Ass’n v. Solimino","cite":"501 U.S. 104","y":1991,"id":"1990/89-1895","sc":1,"sum":"Judicially unreviewed state administrative findings have no preclusive effect on age-discrimination proceedings in federal court. While well-established common-law principles, such as preclusion rules, are presumed to apply in the absence of a legislative intent to the contrary, Congress need not state expressly its intention to overcome a presumption of administrative estoppel. Clear-statement requirements are …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"36"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Fla. Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"44"}},{"t":"case","label":"Free Enter. Fund v. Pub. Co. Acct. Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"2":"2"}},{"t":"case","label":"Grosjean v. Am. Press Co.","cite":"297 U.S. 233","y":1936,"id":"scdb/1935-086","sc":1,"sum":"1. As respects the amount in controversy, the District Court has jurisdiction of a suit where the requisite value is involved as to each of several plaintiffs though not involved as to others.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"33"}},{"t":"case","label":"Interstate Com. Comm’n v. Cincinnati, N.O. & T.P. Ry. Co.","cite":"167 U.S. 479","y":1897,"id":"scdb/1896-212","sc":1,"op":2,"sum":"Congress has not conferred upon the Interstate Commerce Commission the legislative power of prescribing rates either maximum or minimum or absolute; and, as it did not give the express power to the commission, it did not intend to secure the same result indirectly by empowering that tribunal to determine what in reference to the past was reasonable and just, whether as maximum, minimum or absolute, and then enable …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"J.W. Hampton, Jr., & Co. v. United States","cite":"276 U.S. 394","y":1928,"id":"1900-1940/276us394","sc":1,"sum":"The Court held that Congress, within \"defined limits,\" could vest discretion in Executive officers to make public regulations and direct the details of statutory execution. The Court argued that the same principle that allowed Congress to fix rates in interstate commerce also enabled it to remit to a rate-making body under the control of the Executive branch.","sumSrc":"Oyez","by":{"2":"41","9":"17"}},{"t":"case","label":"Minneapolis Star & Tribune Co. v. Minn. Comm’r of Revenue","cite":"460 U.S. 575","y":1983,"id":"1982/81-1839","sc":1,"sum":"The Court held that while the First Amendment did not prohibit all regulation of the press, Minnesota had \"created a special tax that applie[d] only to certain publications protected by the First Amendment.\" Noting that there was \"substantial evidence that differential taxation of the press would have troubled the Framers of the First Amendment,\" the Court held that when states single out the press \"the threat of burdensome taxes becomes acute.\" The Court concluded that \"recognizing a power in the State not only to single out the press but also to tailor the tax so that it singles out a few members of the press presents such a potential for abuse that no interest suggested by Minnesota can justify the scheme.\".","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"New York v. FERC","cite":"535 U.S. 1","y":2002,"id":"2001/00-568","sc":1,"sum":"The Court held that FERC properly construed its statutory authority.","sumSrc":"Oyez","by":{"2":"6","4":"43, 44"}},{"t":"case","label":"Oneok, Inc. v. Learjet, Inc.","cite":"575 U.S. 373","y":2015,"id":"2014/13-271","sc":1,"sum":"The Court held that the Natural Gas Act does not pre-empt state law claims brought by litigants who purchased gas in retail transactions.","sumSrc":"Oyez","by":{"2":"6, 32","9":"13"}},{"t":"case","label":"Panhandle E. Pipe Line Co. v. Pub. Serv. Comm’n of Ind.","cite":"332 U.S. 507","y":1947,"id":"scdb/1947-014","sc":1,"by":{"2":"6"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"34","11":"16"}},{"t":"case","label":"United Sav. Ass’n of Tex. v. Timbers of Inwood Forest Assocs., Ltd.","cite":"484 U.S. 365","y":1988,"id":"1987/86-1602","sc":1,"sum":"Undersecured creditors are not entitled to compensation under § 362(d)(1) for the delay caused by the automatic stay in foreclosing on their collateral.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Vt. Yankee Nuclear Power Corp. v. NRDC","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"7"}},{"t":"case","label":"West Virginia v. EPA","cite":"577 U.S. 1126","y":2016,"url":"https://supreme.justia.com/cases/federal/us/577/1126/","sc":1,"op":1,"by":{"2":"15","4":"9","7":"7, 20"}},{"t":"usc","label":"16 U.S.C. § 824","url":"https://www.law.cornell.edu/uscode/text/16/824","subs":["(b)(1)"],"stext":{"head":"§824. Declaration of policy; application of subchapter","paras":[[0,"(a) Federal regulation of transmission and sale of electric energy"],[0,"It is declared that the business of transmitting and selling electric energy for ultimate distribution to the public is affected with a public interest, and that Federal regulation of matters relating to generation to the extent provided in this subchapter and subchapter III of this chapter and of that part of such business which consists of the transmission of electric energy in interstate commerce and the sale of such energy at wholesale in interstate commerce is necessary in the public interest, such Federal regulation, however, to extend only to those matters which are not subject to regulation by the States."],[0,"(b) Use or sale of electric energy in interstate commerce"],[0,"(1) The provisions of this subchapter shall apply to the transmission of electric energy in interstate commerce and to the sale of electric energy at wholesale in interstate commerce, but except as provided in paragraph (2) shall not apply to any other sale of electric energy or deprive a State or State commission of its lawful authority now exercised over the exportation of hydroelectric energy which is transmitted across a State line. The Commission shall have jurisdiction over all facilities for such transmission or sale of electric energy, but shall not have jurisdiction, except as specifically provided in this subchapter and subchapter III of this chapter, over facilities used for the generation of electric energy or over facilities used in local distribution or only for the transmission of electric energy in intrastate commerce, or over facilities for the transmission of electric energy consumed wholly by the transmitter."],[0,"(2) Notwithstanding subsection (f), the provisions of sections 824b(a)(2), 824e(e), 824i, 824j, 824j–1, 824k, 824o, 824o–1, 824p, 824q, 824r, 824s, 824t, 824u, and 824v of this title shall apply to the entities described in such provisions, and such entities shall be subject to the jurisdiction of the Commission for purposes of carrying out such provisions and for purposes of applying the enforcement authorities of this chapter with respect to such provisions. Compliance with any order or rule of the Commission under the provisions of section 824b(a)(2), 824e(e), 824i, 824j, 824j–1, 824k, 824o, 824o–1, 824p, 824q, 824r, 824s, 824t, 824u, or 824v of this title, shall not make an electric utility or other entity subject to the jurisdiction of the Commission for any purposes other than the purposes specified in the preceding sentence."],[0,"(c) Electric energy in interstate commerce"],[0,"For the purpose of this subchapter, electric energy shall be held to be transmitted in interstate commerce if transmitted from a State and consumed at any point outside thereof; but only insofar as such transmission takes place within the United States."],[0,"(d) \"Sale of electric energy at wholesale\" defined"],[0,"The term \"sale of electric energy at wholesale\" when used in this subchapter, means a sale of electric energy to any person for resale."],[0,"(e) \"Public utility\" defined"],[0,"The term \"public utility\" when used in this subchapter and subchapter III of this chapter means any person who owns or operates facilities subject to the jurisdiction of the Commission under this subchapter (other than facilities subject to such jurisdiction solely by reason of section 824e(e), 824e(f),1 824i, 824j, 824j–1, 824k, 824o, 824o–1, 824p, 824q, 824r, 824s, 824t, 824u, or 824v of this title)."],[0,"(f) United States, State, political subdivision of a State, or agency or instrumentality thereof exempt"],[0,"No provision in this subchapter shall apply to, or be deemed to include, the United States, a State or any political subdivision of a State, an electric cooperative that receives financing under the Rural Electrification Act of 1936 (7 U.S.C. 901 et seq.) or that sells less than 4,000,000 megawatt hours of electricity per year, or any agency, authority, or instrumentality of any one or more of the foregoing, or any corporation which is wholly owned, directly or indirectly, by any one or more of the foregoing, or any officer, agent, or employee of any of the foregoing acting as such in the course of his official duty, unless such provision makes specific reference thereto."],[0,"(g) Books and records"],[0,"(1) Upon written order of a State commission, a State commission may examine the books, accounts, memoranda, contracts, and records of—"],[1,"(A) an electric utility company subject to its regulatory authority under State law,"],[1,"(B) any exempt wholesale generator selling energy at wholesale to such electric utility, and"],[1,"(C) any electric utility company, or holding company thereof, which is an associate company or affiliate of an exempt wholesale generator which sells electric energy to an electric utility company referred to in subparagraph (A),"],[0,"wherever located, if such examination is required for the effective discharge of the State commission's regulatory responsibilities affecting the provision of electric service."],[0,"(2) Where a State commission issues an order pursuant to paragraph (1), the State commission shall not publicly disclose trade secrets or sensitive commercial information."],[0,"(3) Any United States district court located in the State in which the State commission referred to in paragraph (1) is located shall have jurisdiction to enforce compliance with this subsection."],[0,"(4) Nothing in this section shall—"],[1,"(A) preempt applicable State law concerning the provision of records and other information; or"],[1,"(B) in any way limit rights to obtain records and other information under Federal law, contracts, or otherwise."],[0,"(5) As used in this subsection the terms \"affiliate\", \"associate company\", \"electric utility company\", \"holding company\", \"subsidiary company\", and \"exempt wholesale generator\" shall have the same meaning as when used in the Public Utility Holding Company Act of 2005 [42 U.S.C. 16451 et seq.]."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/824?type=usc&year=mostrecent&link-type=html"},"head":"§824. Declaration of policy; application of subchapter","tname":"Conservation","by":{"2":"6","4":"43","5":"12"}},{"t":"usc","label":"42 U.S.C. § 7412","url":"https://www.law.cornell.edu/uscode/text/42/7412","stext":{"head":"§7412. Hazardous air pollutants","paras":[[0,"(a) Definitions"],[0,"For purposes of this section, except subsection (r)—"],[0,"(1) Major source"],[1,"The term \"major source\" means any stationary source or group of stationary sources located within a contiguous area and under common control that emits or has the potential to emit considering controls, in the aggregate, 10 tons per year or more of any hazardous air pollutant or 25 tons per year or more of any combination of hazardous air pollutants. The Administrator may establish a lesser quantity, or in the case of radionuclides different criteria, for a major source than that specified in the previous sentence, on the basis of the potency of the air pollutant, persistence, potential for bioaccumulation, other characteristics of the air pollutant, or other relevant factors."],[0,"(2) Area source"],[1,"The term \"area source\" means any stationary source of hazardous air pollutants that is not a major source. For purposes of this section, the term \"area source\" shall not include motor vehicles or nonroad vehicles subject to regulation under subchapter II."],[0,"(3) Stationary source"],[1,"The term \"stationary source\" shall have the same meaning as such term has under section 7411(a) of this title."],[0,"(4) New source"],[1,"The term \"new source\" means a stationary source the construction or reconstruction of which is commenced after the Administrator first proposes regulations under this section establishing an emission standard applicable to such source."],[0,"(5) Modification"],[1,"The term \"modification\" means any physical change in, or change in the method of operation of, a major source which increases the actual emissions of any hazardous air pollutant emitted by such source by more than a de minimis amount or which results in the emission of any hazardous air pollutant not previously emitted by more than a de minimis amount."],[0,"(6) Hazardous air pollutant"],[1,"The term \"hazardous air pollutant\" means any air pollutant listed pursuant to subsection (b)."],[0,"(7) Adverse environmental effect"],[1,"The term \"adverse environmental effect\" means any significant and widespread adverse effect, which may reasonably be anticipated, to wildlife, aquatic life, or other natural resources, including adverse impacts on populations of endangered or threatened species or significant degradation of environmental quality over broad areas."],[0,"(8) Electric utility steam generating unit"],[1,"The term \"electric utility steam generating unit\" means any fossil fuel fired combustion unit of more than 25 megawatts that serves a generator that produces electricity for sale. A unit that cogenerates steam and electricity and supplies more than one-third of its potential electric output capacity and more than 25 megawatts electrical output to any utility power distribution system for sale shall be considered an electric utility steam generating unit."],[0,"(9) Owner or operator"],[1,"The term \"owner or operator\" means any person who owns, leases, operates, controls, or supervises a stationary source."],[0,"(10) Existing source"],[1,"The term \"existing source\" means any stationary source other than a new source."],[0,"(11) Carcinogenic effect"],[1,"Unless revised, the term \"carcinogenic effect\" shall have the meaning provided by the Administrator under Guidelines for Carcinogenic Risk Assessment as of the date of enactment.1 Any revisions in the existing Guidelines shall be subject to notice and opportunity for comment."],[0,"(b) List of pollutants"],[0,"(1) Initial list"],[1,"The Congress establishes for purposes of this section a list of hazardous air pollutants as follows:"],[0,"NOTE: For all listings above which contain the word \"compounds\" and for glycol ethers, the following applies: Unless otherwise specified, these listings are defined as including any unique chemical substance that contains the named chemical (i.e., antimony, arsenic, etc.) as part of that chemical's infrastructure."],[0,"1 X′CN where X = H′ or any other group where a formal dissociation may occur. For example KCN or Ca(CN)2."],[0,"2 Includes mono- and di- ethers of ethylene glycol, diethylene glycol, and triethylene glycol R–(OCH2CH2)n–OR′ where"],[0,"n = 1, 2, or 3"],[0,"R = alkyl or aryl groups"],[0,"R′ = R, H, or groups which, when removed, yield glycol ethers with the structure: R–(OCH2CH)n–OH. Polymers are excluded from the glycol category."],[0,"3 Includes mineral fiber emissions from facilities manufacturing or processing glass, rock, or slag fibers (or other mineral derived fibers) of average diameter 1 micrometer or less."],[0,"4 Includes organic compounds with more than one benzene ring, and which have a boiling point greater than or equal to 100°C."],[0,"5 A type of atom which spontaneously undergoes radioactive decay."],[0,"(2) Revision of the list"],[1,"The Administrator shall periodically review the list established by this subsection and publish the results thereof and, where appropriate, revise such list by rule, adding pollutants which present, or may present, through inhalation or other routes of exposure, a threat of adverse human health effects (including, but not limited to, substances which are known to be, or may reasonably be anticipated to be, carcinogenic, mutagenic, teratogenic, neurotoxic, which cause reproductive dysfunction, or which are acutely or chronically toxic) or adverse environmental effects whether through ambient concentrations, bioaccumulation, deposition, or otherwise, but not including releases subject to regulation under subsection (r) as a result of emissions to the air. No air pollutant which is listed under section 7408(a) of this title may be added to the list under this section, except that the prohibition of this sentence shall not apply to any pollutant which independently meets the listing criteria of this paragraph and is a precursor to a pollutant which is listed under section 7408(a) of this title or to any pollutant which is in a class of pollutants listed under such section. No substance, practice, process or activity regulated under subchapter VI of this chapter shall be subject to regulation under this section solely due to its adverse effects on the environment."],[0,"(3) Petitions to modify the list"],[1,"(A) Beginning at any time after 6 months after November 15, 1990, any person may petition the Administrator to modify the list of hazardous air pollutants under this subsection by adding or deleting a substance or, in case of listed pollutants without CAS numbers (other than coke oven emissions, mineral fibers, or polycyclic organic matter) removing certain unique substances. Within 18 months after receipt of a petition, the Administrator shall either grant or deny the petition by publishing a written explanation of the reasons for the Administrator's decision. Any such petition shall include a showing by the petitioner that there is adequate data on the health or environmental defects 2 of the pollutant or other evidence adequate to support the petition. The Administrator may not deny a petition solely on the basis of inadequate resources or time for review."],[1,"(B) The Administrator shall add a substance to the list upon a showing by the petitioner or on the Administrator's own determination that the substance is an air pollutant and that emissions, ambient concentrations, bioaccumulation or deposition of the substance are known to cause or may reasonably be anticipated to cause adverse effects to human health or adverse environmental effects."],[1,"(C) The Administrator shall delete a substance from the list upon a showing by the petitioner or on the Administrator's own determination that there is adequate data on the health and environmental effects of the substance to determine that emissions, ambient concentrations, bioaccumulation or deposition of the substance may not reasonably be anticipated to cause any adverse effects to the human health or adverse environmental effects."],[1,"(D) The Administrator shall delete one or more unique chemical substances that contain a listed hazardous air pollutant not having a CAS number (other than coke oven emissions, mineral fibers, or polycyclic organic matter) upon a showing by the petitioner or on the Administrator's own determination that such unique chemical substances that contain the named chemical of such listed hazardous air pollutant meet the deletion requirements of subparagraph (C). The Administrator must grant or deny a deletion petition prior to promulgating any emission standards pursuant to subsection (d) applicable to any source category or subcategory of a listed hazardous air pollutant without a CAS number listed under subsection (b) for which a deletion petition has been filed within 12 months of November 15, 1990."],[0,"(4) Further information"],[1,"If the Administrator determines that information on the health or environmental effects of a substance is not sufficient to make a determination required by this subsection, the Administrator may use any authority available to the Administrator to acquire such information."],[0,"(5) Test methods"],[1,"The Administrator may establish, by rule, test measures and other analytic procedures for monitoring and measuring emissions, ambient concentrations, deposition, and bioaccumulation of hazardous air pollutants."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7412?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7412. Hazardous air pollutants","tname":"The Public Health and Welfare","by":{"2":"38","6":"21","7":"3","8":"15, 16"}},{"t":"usc","label":"42 U.S.C. § 7479","url":"https://www.law.cornell.edu/uscode/text/42/7479","subs":["(3)"],"stext":{"head":"§7479. Definitions","paras":[[0,"For purposes of this part—"],[1,"(1) The term \"major emitting facility\" means any of the following stationary sources of air pollutants which emit, or have the potential to emit, one hundred tons per year or more of any air pollutant from the following types of stationary sources: fossil-fuel fired steam electric plants of more than two hundred and fifty million British thermal units per hour heat input, coal cleaning plants (thermal dryers), kraft pulp mills, Portland Cement plants, primary zinc smelters, iron and steel mill plants, primary aluminum ore reduction plants, primary copper smelters, municipal incinerators capable of charging more than fifty tons of refuse per day, hydrofluoric, sulfuric, and nitric acid plants, petroleum refineries, lime plants, phosphate rock processing plants, coke oven batteries, sulfur recovery plants, carbon black plants (furnace process), primary lead smelters, fuel conversion plants, sintering plants, secondary metal production facilities, chemical process plants, fossil-fuel boilers of more than two hundred and fifty million British thermal units per hour heat input, petroleum storage and transfer facilities with a capacity exceeding three hundred thousand barrels, taconite ore processing facilities, glass fiber processing plants, charcoal production facilities. Such term also includes any other source with the potential to emit two hundred and fifty tons per year or more of any air pollutant. This term shall not include new or modified facilities which are nonprofit health or education institutions which have been exempted by the State."],[1,"(2)(A) The term \"commenced\" as applied to construction of a major emitting facility means that the owner or operator has obtained all necessary preconstruction approvals or permits required by Federal, State, or local air pollution emissions and air quality laws or regulations and either has (i) begun, or caused to begin, a continuous program of physical on-site construction of the facility or (ii) entered into binding agreements or contractual obligations, which cannot be canceled or modified without substantial loss to the owner or operator, to undertake a program of construction of the facility to be completed within a reasonable time."],[1,"(B) The term \"necessary preconstruction approvals or permits\" means those permits or approvals, required by the permitting authority as a precondition to undertaking any activity under clauses (i) or (ii) of subparagraph (A) of this paragraph."],[1,"(C) The term \"construction\" when used in connection with any source or facility, includes the modification (as defined in section 7411(a) of this title) of any source or facility."],[1,"(3) The term \"best available control technology\" means an emission limitation based on the maximum degree of reduction of each pollutant subject to regulation under this chapter emitted from or which results from any major emitting facility, which the permitting authority, on a case-by-case basis, taking into account energy, environmental, and economic impacts and other costs, determines is achievable for such facility through application of production processes and available methods, systems, and techniques, including fuel cleaning, clean fuels, or treatment or innovative fuel combustion techniques for control of each such pollutant. In no event shall application of \"best available control technology\" result in emissions of any pollutants which will exceed the emissions allowed by any applicable standard established pursuant to section 7411 or 7412 of this title. Emissions from any source utilizing clean fuels, or any other means, to comply with this paragraph shall not be allowed to increase above levels that would have been required under this paragraph as it existed prior to November 15, 1990."],[1,"(4) The term \"baseline concentration\" means, with respect to a pollutant, the ambient concentration levels which exist at the time of the first application for a permit in an area subject to this part, based on air quality data available in the Environmental Protection Agency or a State air pollution control agency and on such monitoring data as the permit applicant is required to submit. Such ambient concentration levels shall take into account all projected emissions in, or which may affect, such area from any major emitting facility on which construction commenced prior to January 6, 1975, but which has not begun operation by the date of the baseline air quality concentration determination. Emissions of sulfur oxides and particulate matter from any major emitting facility on which construction commenced after January 6, 1975, shall not be included in the baseline and shall be counted against the maximum allowable increases in pollutant concentrations established under this part."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7479?type=usc&year=mostrecent&link-type=html"},"head":"§7479. Definitions","tname":"The Public Health and Welfare","by":{"2":"27","3":"40","6":"21"}},{"t":"usc","label":"42 U.S.C. § 7521","url":"https://www.law.cornell.edu/uscode/text/42/7521","by":{"2":"40"}},{"t":"usc","label":"42 U.S.C. § 7671","url":"https://www.law.cornell.edu/uscode/text/42/7671","by":{"2":"39"}},{"t":"reg","label":"40 C.F.R. pt. 60","url":"https://www.ecfr.gov/current/title-40/part-60","by":{"2":"7","6":"23"}},{"t":"reg","label":"80 Fed. Reg. 64,509","url":"https://www.govinfo.gov/link/fr/80/64509","by":{"2":"13"}},{"t":"reg","label":"80 Fed. Reg. 64,662","url":"https://www.govinfo.gov/link/fr/80/64662","by":{"2":"passim","3":"passim","4":"passim","9":"passim","10":"passim"}},{"t":"reg","label":"84 Fed. Reg. 32,520","url":"https://www.govinfo.gov/link/fr/84/32520","by":{"2":"passim","3":"passim","4":"passim","9":"passim","10":"passim"}},{"t":"case","label":"Jennifer Mascott, Gundy v. United States: Reflections on the Court and the State of the Nondelegation Doctrine","cite":"26 Geo. Mason L. Rev. 1","y":2018,"url":"https://www.courtlistener.com/c/Geo.%20Mason%20L.%20Rev./26/1/","by":{"2":"25"}},{"t":"reg","label":"Tackling the Climate Crisis at Home and Abroad, Executive Order No. 14,008, 86 Fed. Reg. 7619","url":"https://www.govinfo.gov/link/fr/86/7619","by":{"2":"28"}},{"t":"case","label":"American Corn Growers Ass’n v. EPA","cite":"291 F.3d 1","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/291/1/","by":{"3":"43, 44, 45"}},{"t":"case","label":"American Lung Ass’n v. EPA","cite":"985 F.3d 914","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/985/914/","op":7,"by":{"3":"1, 24","5":"1"}},{"t":"case","label":"BCCA Appeal Group v. EPA","cite":"355 F.3d 817","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/355/817/","by":{"3":"11, 12","11":"10"}},{"t":"case","label":"Connecticut Nat. Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"34"}},{"t":"case","label":"Desert Palace, Inc. v. Costa","cite":"539 U.S. 90","y":2003,"id":"2002/02-679","sc":1,"sum":"The Court held that direct evidence is not required.","sumSrc":"Oyez","by":{"3":"33"}},{"t":"case","label":"FCC v. RCA Commc’ns","cite":"346 U.S. 86","y":1953,"id":"scdb/1952-103","sc":1,"sum":"Under the Federal Communications Act of 1934, the Commission authorized a radiotelegraph company, which was then serving 39 overseas points, to open two new circuits, to Portugal and The Netherlands. The authorization was opposed by another company which provided similar service by means of 65 circuits, including circuits to each of those countries. The Commission concluded that duplicate facilities should be …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"General Motors Corp. v. United States","cite":"496 U.S. 530","y":1990,"id":"1989/89-369","sc":1,"sum":"The Clean Air Act was amended in 1970 to deal with a perceived national air-pollution emergency. The amendments required that the Administrator of the Environmental Protection Agency (EPA) promulgate national ambient air quality standards (NAAQS) within 30 days and that each State thereafter submit a state implementation plan (SIP) within nine months. Section 110(a)(2) of the Act required the Administrator to …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"11"}},{"t":"case","label":"Guardians Ass’n v. Civil Serv. Comm’n of the City of New York","cite":"463 U.S. 582","y":1983,"id":"1982/81-431","sc":1,"sum":"The judgment is affirmed. 633 F. 2d 232, affirmed. JUSTICE WHITE concluded that discriminatory intent is not an essential element of a Title VI violation. JUSTICE WHITE, joined by JUSTICE REHNQUIST, also concluded that a private plaintiff should recover only injunctive, noncompensatory relief for a defendant's unintentional violation of Title VI, that such relief should not include an award of constructive …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"30"}},{"t":"case","label":"Hartford Underwriters Ins. Co. v. Union Planters Bank, N. A.","cite":"530 U.S. 1","y":2000,"id":"1999/99-409","sc":1,"sum":"The Court held that \"Section 506(c) does not provide an administrative claimant of a bankruptcy estate an independent right to seek payment of its claim from property encumbered by a secured creditor's lien, or subject to secured claims.","sumSrc":"Oyez","by":{"3":"34"}},{"t":"case","label":"King v. St. Vincent’s Hospital","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"sum":"Section 2024(d) does not limit the length of military service after which a member of the Armed Forces retains a right to civilian reemployment. Subsection (d)'s text-which specifies that any covered employee \"shall... be granted a leave... for the period required to perform active duty [and] [u]pon... release from... such duty... shall be permitted to return to [his or her] position\"-is utterly silent about any …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"28, 51"}},{"t":"case","label":"Louisiana Public Serv. Comm’n v. FCC","cite":"476 U.S. 355","y":1986,"id":"1985/84-871","sc":1,"op":1,"sum":"Section 152(b) bars federal pre-emption of state regulation over depreciation of dual jurisdiction property for intrastate ratemaking purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"30"}},{"t":"case","label":"Prill v. NLRB","cite":"755 F.2d 941","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/755/941/","by":{"3":"5"}},{"t":"case","label":"U.S. v. Atlantic Research Corp.","cite":"551 U.S. 128","y":2007,"id":"2006/06-562","sc":1,"sum":"The Court ruled unanimously that Section 107(a) of CERCLA allows potentially responsible parties (PRPs) to sue other PRPs for cost recovery. The opinion by Justice Clarence Thomas affirmed the Eighth Circuit and ruled for Atlantic Research.","sumSrc":"Oyez","by":{"3":"28, 51"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(C)"],"by":{"3":"30"}},{"t":"usc","label":"42 U.S.C. § 7407","url":"https://www.law.cornell.edu/uscode/text/42/7407","subs":["(a)"],"by":{"3":"12"}},{"t":"case","label":"BST Holdings, L.L.C. v. OSHA","cite":"17 F.4th 604","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/17/604/","op":1,"by":{"4":"1"}},{"t":"case","label":"Christensen v. Harris Cty.","cite":"529 U.S. 576","y":2000,"id":"1999/98-1167","sc":1,"op":18,"sum":"Noting that for decades the FDA had said it lacked statutory power to regulate cigarettes.","sumSrc":"opinion","by":{"4":"19, 28"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"sum":"A case in which the Court declared that pieces of legislation passed by both houses of Congress must be either passed or vetoed as a whole, not in separate parts.","sumSrc":"Oyez","by":{"4":"20"}},{"t":"case","label":"Conn. Dep’t of Pub. Util. Control v. FERC","cite":"569 F.3d 477","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/569/477/","op":1,"by":{"4":"42"}},{"t":"case","label":"District of Columbia v. Dep’t of Labor","cite":"819 F.3d 444","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/819/444/","by":{"4":"30"}},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"556 U.S. 502","y":2009,"id":"2008/07-582","sc":1,"sum":"The Court held that the FCC's imposition of liability on Fox Television Stations for fleeting expletives was not \"arbitrary and capricious\" under the Administrative Procedure Act, even though the FCC previously accepted similar expletives.","sumSrc":"Oyez","by":{"4":"27","8":"21"}},{"t":"case","label":"Fed. Power Comm’n v. S. Cal. Edison Co.","cite":"376 U.S. 205","y":1964,"id":"1963/71","sc":1,"sum":"Petitioner, a California municipality, purchased electric energy, part of which was from out-of-state, from respondent public utility company, using some for itself but reselling the bulk to others. The respondent Public Utilities Commission of California had previously exercised jurisdiction over the rates charged the city by the public utility company, but on the city's petition the petitioner Federal Power …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"42"}},{"t":"usc","label":"16 U.S.C. § 824o","url":"https://www.law.cornell.edu/uscode/text/16/824o","subs":["(a)(2)","(b)(1)","(e)"],"by":{"4":"43","5":"13, 12, 14"}},{"t":"law","label":"Pub. L. No. 91-604","url":"https://www.govinfo.gov/link/statute/84/1676","by":{"4":"4","7":"32"}},{"t":"case","label":"Del. Dep’t of Nat. Res. & Envtl. Control v. Envtl. Prot. Agency","cite":"785 F.3d 1","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/785/1/","by":{"5":"12, 13","11":"5"}},{"t":"reg","label":"18 C.F.R. § 39.2","url":"https://www.ecfr.gov/current/title-18/section-39.2","subs":["(b)"],"by":{"5":"13"}},{"t":"reg","label":"18 C.F.R. § 40.2","url":"https://www.ecfr.gov/current/title-18/section-40.2","by":{"5":"13"}},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"579 U.S. 261","y":2016,"id":"2015/15-446","sc":1,"sum":"The Court held that the Patent Trial and Appeal Board may apply the broadest reasonable interpretation of patent claims during an inter partes review proceeding, and such a proceeding is not judicially reviewable.","sumSrc":"Oyez","by":{"6":"9"}},{"t":"case","label":"Dep’t of Transp. v. Ass’n of Am. RRs.","cite":"575 U.S. 43","y":2015,"id":"2014/13-1080","sc":1,"op":1,"sum":"The Court held that for purposes of the validity of metrics and standards, Amtrak is a governmental entity.","sumSrc":"Oyez","by":{"6":"9"}},{"t":"case","label":"Gutierrez-Brizuela v. Lynch","cite":"834 F.3d 1142","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/834/1142/","sum":"Explaining that even if Congress intended to delegate legislative authority through ambiguity “[t]he Supreme Court has long recognized that under the Constitution ‘congress cannot delegate legislative power to the president’”.","sumSrc":"brief:6","by":{"6":"9"}},{"t":"case","label":"Marbury v. Madison","cite":"1 Cranch 137","y":1803,"url":"https://www.courtlistener.com/c/Cranch/1/137/","by":{"6":"11"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n of the U.S., Inc. v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"6":"8"}},{"t":"case","label":"Perez v. Mortg. Bankers Ass’n","cite":"575 U.S. 92","y":2015,"id":"2014/13-1041","sc":1,"sum":"The Court ruled that federal agencies do not need to engage in a notice-and-comment procedure before significantly altering an interpretation of a rule of agency regulation.","sumSrc":"Oyez","by":{"6":"7"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"6":"8"}},{"t":"usc","label":"33 U.S.C. § 1311","url":"https://www.law.cornell.edu/uscode/text/33/1311","by":{"6":"21"}},{"t":"usc","label":"33 U.S.C. § 1313","url":"https://www.law.cornell.edu/uscode/text/33/1313","by":{"6":"21"}},{"t":"usc","label":"33 U.S.C. § 1316","url":"https://www.law.cornell.edu/uscode/text/33/1316","by":{"6":"21"}},{"t":"const","label":"Article I, Section 1","clauses":[["legislative-vesting","Legislative Vesting Clause"]],"text":"All legislative Powers herein granted shall be vested in a Congress of the United States, which shall consist of a Senate and House of Representatives.","by":{"6":"7"}},{"t":"case","label":"Arizonans for Official English v. Arizona","cite":"520 U.S. 43","y":1997,"id":"1996/95-974","sc":1,"op":1,"sum":"Announced by Justice Ruth Bader Ginsburg, the Court held that the dispute was moot due to the previous resignation of Yniguez. The Court did not rule on the constitutionality of the article.","sumSrc":"Oyez","by":{"7":"15","11":"20"}},{"t":"case","label":"Biden v. Sierra Club","cite":"142 S. Ct. 46","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./142/46/","sc":1,"op":1,"by":{"7":"22"}},{"t":"case","label":"Camreta v. Greene","cite":"563 U.S. 692","y":2011,"id":"2010/09-1454","sc":1,"sum":"A case which the Court vacated in part and remanded in favor of the defendant without addressing the Fourth Amendment question at issue.","sumSrc":"Oyez","by":{"7":"23"}},{"t":"case","label":"Clapper v. Amnesty Int’l USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"7":"19, 20"}},{"t":"case","label":"Diamond v. Charles","cite":"476 U.S. 54","y":1986,"id":"1985/84-1379","sc":1,"sum":"Because appellant lacks any judicially cognizable interest in the Illinois Abortion Law, his appeal is dismissed for want of jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"7":"15, 18, 21","9":"19","11":"20"}},{"t":"case","label":"EPA v. EME Homer City Generation, L. P.","cite":"572 U.S. 489","y":2014,"id":"2013/12-1182","sc":1,"op":1,"sum":"The Court held that the EPA has an absolute mandate to require states to meet federal standards set forth in the Clean Air Act.","sumSrc":"Oyez","by":{"7":"31","10":"10, 11"}},{"t":"case","label":"Essex Chem. Corp. v. Ruckelshaus","cite":"486 F.2d 427","y":1973,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/486/427/","by":{"7":"42","8":"13","9":"3, 9, 17"}},{"t":"case","label":"Federal Land Bank v. Bismarck Lumber Co.","cite":"314 U.S. 95","y":1941,"id":"scdb/1941-013","sc":1,"by":{"7":"37"}},{"t":"case","label":"Hollingsworth v. Perry","cite":"570 U.S. 693","y":2013,"id":"2012/12-144","sc":1,"op":1,"sum":"The Court found that the proponents of California's same-sex marriage ban (Proposition 8) do not have standing to appeal the decision that made Proposition 8 unconstitutional.","sumSrc":"Oyez","by":{"7":"15, 20","11":"20"}},{"t":"case","label":"Lawrence v. Chater","cite":"516 U.S. 163","y":1996,"id":"1995/94-9323","sc":1,"sum":"In a 7-2 per curiam opinion, the Court held that it had the power to issue a GVR order and that such an order is an appropriate exercise of its discretionary certiorari jurisdiction. \"In an appropriate case, a GVR order conserves the scarce resources of this Court that might otherwise be expended on plenary consideration, assists the court below by flagging a particular issue that it does not appear to have fully considered, assists this Court by procuring the benefit of the lower court's insight before we rule on the merits, and alleviates the 'potential for unequal treatment' that is inherent in our inability to grant plenary review of all pending cases raising similar issues,\" stated the unsigned opinion.","sumSrc":"Oyez","by":{"7":"22"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"op":1,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"7":"15","9":"21","10":"6, 10","11":"19, 20"}},{"t":"case","label":"National Fed’n of Indep. Bus. v. Department of Labor","cite":"2022 WL 120952","y":2022,"court":"U.S. Jan. 13","by":{"7":"46, 48"}},{"t":"case","label":"Sierra Club v. Costle","cite":"657 F.2d 298","y":1981,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/657/298/","by":{"7":"42","8":"13"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"op":13,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"7":"20","11":"22"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"7":"19"}},{"t":"case","label":"Trump v. New York","cite":"141 S. Ct. 530","y":2020,"id":"2020/20-366","sc":1,"op":5,"sum":"Because plaintiffs have not shown standing and because the claims presented are not ripe for adjudication, the District Court’s judgment is vacated, and the case is remanded with instructions to dismiss for lack of jurisdiction.","sumSrc":"Holding (supremecourt.gov)","by":{"7":"21"}},{"t":"case","label":"U.S. Bancorp Mortg. Co. v. Bonner Mall P’ship","cite":"513 U.S. 18","y":1994,"id":"1994/93-714","sc":1,"sum":"After this Court granted the petition for a writ of certiorari and received briefing on the merits, the parties entered into a settlement and agreed that the case was thereby mooted. Petitioner, however, also requested that the Court exercise its power under 28 U. S. C. § 2106 to vacate the judgment of the Court of Appeals. Respondent opposed the motion.","sumSrc":"Syllabus (U.S. Reports)","by":{"7":"22"}},{"t":"case","label":"United States v. Munsingwear, Inc.","cite":"340 U.S. 36","y":1950,"id":"scdb/1950-004","sc":1,"sum":"The dismissal is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"7":"22","11":"18"}},{"t":"case","label":"Van Buren v. United States","cite":"141 S. Ct. 1648","y":2021,"id":"2020/19-783","sc":1,"sum":"An individual “exceeds authorized access” under the Computer Fraud and Abuse Act of 1986, 18 U. S. C. §1030(a)(2), when he accesses a computer with authorization but then obtains information located in particular areas of the computer—such as files, folders, or databases—that are off-limits to him.","sumSrc":"Holding (supremecourt.gov)","by":{"7":"33"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"7":"15, 19"}},{"t":"usc","label":"42 U.S.C. § 7408","url":"https://www.law.cornell.edu/uscode/text/42/7408","subs":["(a)"],"stext":{"head":"§7408. Air quality criteria and control techniques","paras":[[0,"(a) Air pollutant list; publication and revision by Administrator; issuance of air quality criteria for air pollutants"],[0,"(1) For the purpose of establishing national primary and secondary ambient air quality standards, the Administrator shall within 30 days after December 31, 1970, publish, and shall from time to time thereafter revise, a list which includes each air pollutant—"],[1,"(A) emissions of which, in his judgment, cause or contribute to air pollution which may reasonably be anticipated to endanger public health or welfare;"],[1,"(B) the presence of which in the ambient air results from numerous or diverse mobile or stationary sources; and"],[1,"(C) for which air quality criteria had not been issued before December 31, 1970 but for which he plans to issue air quality criteria under this section."],[0,"(2) The Administrator shall issue air quality criteria for an air pollutant within 12 months after he has included such pollutant in a list under paragraph (1). Air quality criteria for an air pollutant shall accurately reflect the latest scientific knowledge useful in indicating the kind and extent of all identifiable effects on public health or welfare which may be expected from the presence of such pollutant in the ambient air, in varying quantities. The criteria for an air pollutant, to the extent practicable, shall include information on—"],[1,"(A) those variable factors (including atmospheric conditions) which of themselves or in combination with other factors may alter the effects on public health or welfare of such air pollutant;"],[1,"(B) the types of air pollutants which, when present in the atmosphere, may interact with such pollutant to produce an adverse effect on public health or welfare; and"],[1,"(C) any known or anticipated adverse effects on welfare."],[0,"(b) Issuance by Administrator of information on air pollution control techniques; standing consulting committees for air pollutants; establishment; membership"],[0,"(1) Simultaneously with the issuance of criteria under subsection (a), the Administrator shall, after consultation with appropriate advisory committees and Federal departments and agencies, issue to the States and appropriate air pollution control agencies information on air pollution control techniques, which information shall include data relating to the cost of installation and operation, energy requirements, emission reduction benefits, and environmental impact of the emission control technology. Such information shall include such data as are available on available technology and alternative methods of prevention and control of air pollution. Such information shall also include data on alternative fuels, processes, and operating methods which will result in elimination or significant reduction of emissions."],[0,"(2) In order to assist in the development of information on pollution control techniques, the Administrator may establish a standing consulting committee for each air pollutant included in a list published pursuant to subsection (a)(1), which shall be comprised of technically qualified individuals representative of State and local governments, industry, and the academic community. Each such committee shall submit, as appropriate, to the Administrator information related to that required by paragraph (1)."],[0,"(c) Review, modification, and reissuance of criteria or information"],[0,"The Administrator shall from time to time review, and, as appropriate, modify, and reissue any criteria or information on control techniques issued pursuant to this section. Not later than six months after August 7, 1977, the Administrator shall revise and reissue criteria relating to concentrations of NO2 over such period (not more than three hours) as he deems appropriate. Such criteria shall include a discussion of nitric and nitrous acids, nitrites, nitrates, nitrosamines, and other carcinogenic and potentially carcinogenic derivatives of oxides of nitrogen."],[0,"(d) Publication in Federal Register; availability of copies for general public"],[0,"The issuance of air quality criteria and information on air pollution control techniques shall be announced in the Federal Register and copies shall be made available to the general public."],[0,"(e) Transportation planning and guidelines"],[0,"The Administrator shall, after consultation with the Secretary of Transportation, and after providing public notice and opportunity for comment, and with State and local officials, within nine months after November 15, 1990,1 and periodically thereafter as necessary to maintain a continuous transportation-air quality planning process, update the June 1978 Transportation-Air Quality Planning Guidelines and publish guidance on the development and implementation of transportation and other measures necessary to demonstrate and maintain attainment of national ambient air quality standards. Such guidelines shall include information on—"],[1,"(1) methods to identify and evaluate alternative planning and control activities;"],[1,"(2) methods of reviewing plans on a regular basis as conditions change or new information is presented;"],[1,"(3) identification of funds and other resources necessary to implement the plan, including interagency agreements on providing such funds and resources;"],[1,"(4) methods to assure participation by the public in all phases of the planning process; and"],[1,"(5) such other methods as the Administrator determines necessary to carry out a continuous planning process."],[0,"(f) Information regarding processes, procedures, and methods to reduce or control pollutants in transportation; reduction of mobile source related pollutants; reduction of impact on public health"],[0,"(1) The Administrator shall publish and make available to appropriate Federal, State, and local environmental and transportation agencies not later than one year after November 15, 1990, and from time to time thereafter—"],[1,"(A) information prepared, as appropriate, in consultation with the Secretary of Transportation, and after providing public notice and opportunity for comment, regarding the formulation and emission reduction potential of transportation control measures related to criteria pollutants and their precursors, including, but not limited to—"],[2,"(i) programs for improved public transit;"],[2,"(ii) restriction of certain roads or lanes to, or construction of such roads or lanes for use by, passenger buses or high occupancy vehicles;"],[2,"(iii) employer-based transportation management plans, including incentives;"],[2,"(iv) trip-reduction ordinances;"],[2,"(v) traffic flow improvement programs that achieve emission reductions;"],[2,"(vi) fringe and transportation corridor parking facilities serving multiple occupancy vehicle programs or transit service;"],[2,"(vii) programs to limit or restrict vehicle use in downtown areas or other areas of emission concentration particularly during periods of peak use;"],[2,"(viii) programs for the provision of all forms of high-occupancy, shared-ride services;"],[2,"(ix) programs to limit portions of road surfaces or certain sections of the metropolitan area to the use of non-motorized vehicles or pedestrian use, both as to time and place;"],[2,"(x) programs for secure bicycle storage facilities and other facilities, including bicycle lanes, for the convenience and protection of bicyclists, in both public and private areas;"],[2,"(xi) programs to control extended idling of vehicles;"],[2,"(xii) programs to reduce motor vehicle emissions, consistent with subchapter II, which are caused by extreme cold start conditions;"],[2,"(xiii) employer-sponsored programs to permit flexible work schedules;"],[2,"(xiv) programs and ordinances to facilitate non-automobile travel, provision and utilization of mass transit, and to generally reduce the need for single-occupant vehicle travel, as part of transportation planning and development efforts of a locality, including programs and ordinances applicable to new shopping centers, special events, and other centers of vehicle activity;"],[2,"(xv) programs for new construction and major reconstructions of paths, tracks or areas solely for the use by pedestrian or other non-motorized means of transportation when economically feasible and in the public interest. For purposes of this clause, the Administrator shall also consult with the Secretary of the Interior; and"],[2,"(xvi) program to encourage the voluntary removal from use and the marketplace of pre-1980 model year light duty vehicles and pre-1980 model light duty trucks.2"],[1,"(B) information on additional methods or strategies that will contribute to the reduction of mobile source related pollutants during periods in which any primary ambient air quality standard will be exceeded and during episodes for which an air pollution alert, warning, or emergency has been declared;"],[1,"(C) information on other measures which may be employed to reduce the impact on public health or protect the health of sensitive or susceptible individuals or groups; and"],[1,"(D) information on the extent to which any process, procedure, or method to reduce or control such air pollutant may cause an increase in the emissions or formation of any other pollutant."],[0,"(2) In publishing such information the Administrator shall also include an assessment of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7408?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7408. Air quality criteria and control techniques","tname":"The Public Health and Welfare","by":{"7":"3, 29"}},{"t":"usc","label":"42 U.S.C. § 7651b","url":"https://www.law.cornell.edu/uscode/text/42/7651b","subs":["(a)(1)"],"by":{"7":"37"}},{"t":"law","label":"Pub. L. No. 95-95","url":"https://www.govinfo.gov/link/statute/91/700","by":{"7":"32"}},{"t":"law","label":"Pub. L. No. 101-549","url":"https://www.govinfo.gov/link/statute/104/2631","by":{"7":"32"}},{"t":"usc","label":"28 U.S.C. § 2106","url":"https://www.law.cornell.edu/uscode/text/28/2106","by":{"7":"22"}},{"t":"case","label":"ASARCO Inc. v. Kadish","cite":"490 U.S. 605","y":1989,"id":"1988/87-1661","sc":1,"sum":"The judgment is affirmed. 155 Ariz. 484, 747 P. 2d 1183, affirmed. JUSTICE KENNEDY delivered the opinion of the Court with respect to Parts I, II-A, II-B-2, II-C, III, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"8":"18"}},{"t":"case","label":"Bloate v. United States","cite":"559 U.S. 196","y":2010,"id":"2009/08-728","sc":1,"sum":"The Court held that the time granted to prepare pretrial motions is not automatically granted exclusion from the Speedy Trial Act's 70-day time limit.","sumSrc":"Oyez","by":{"8":"15"}},{"t":"case","label":"Chafin v. Chafin","cite":"568 U.S. 165","y":2013,"id":"2012/11-1347","sc":1,"sum":"The Court decided that the return of a child to his or her country of residence pursuant to The Hague Convention, does not make an appeal of that order moot.","sumSrc":"Oyez","by":{"8":"18, 19","10":"9"}},{"t":"case","label":"City of Mesquite v. Aladdin’s Castle, Inc.","cite":"455 U.S. 283","y":1982,"id":"1981/80-1577","sc":1,"op":1,"sum":"Section 6 of appellant Texas city's licensing ordinance governing coin-operated amusement establishments directs the Chief of Police to consider whether a license applicant has any \"connections with criminal elements.\" After receiving recommendations from the Chief of Police, the Chief Building Inspector, and the City Planner, the City Manager decides whether to grant a license. If he denies the license, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"8":"19","11":"21"}},{"t":"case","label":"Deposit Guar. Nat’l Bank v. Roper","cite":"445 U.S. 326","y":1980,"id":"1979/78-904","sc":1,"sum":"Neither petitioner's tender nor the District Court's entry of judgment in favor of respondents over their objections mooted their private case or controversy, and their individual interest in the litigation-as distinguished from whatever may be their representative responsibilities to the putative class-is sufficient to permit their appeal of the adverse certification ruling.","sumSrc":"Syllabus (U.S. Reports)","by":{"8":"18"}},{"t":"case","label":"Hearth, Patio & Barbecue Ass’n v. EPA","cite":"11 F.4th 791","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/11/791/","by":{"8":"9"}},{"t":"case","label":"Knox v. SEIU","cite":"567 U.S. 298","y":2012,"id":"2011/10-1121","sc":1,"sum":"The Court found that, under the First Amendment, public-sector unions are not permitted to impose a special assessment fee without the consent of the member upon whom it is imposed.","sumSrc":"Oyez","by":{"8":"18, 19"}},{"t":"case","label":"NFIB v. DOL","cite":"142 S. Ct. 661","y":2022,"url":"https://www.courtlistener.com/c/S.%20Ct./142/661/","sc":1,"op":6,"by":{"8":"6, 7, 8, 10","9":"11, 13, 14","11":"1, 2"}},{"t":"case","label":"Nw. Fuel Co. v. Brock","cite":"139 U.S. 216","y":1891,"id":"scdb/1890-166","sc":1,"sum":"The judgment in this case was reversed in this' court for want of jurisdiction in the Circuit Court, 130 U. S. 341. The reversal was accompanied by an order that the defendants recover their costs in this court; and have execution therefor, and the cause was remanded to the Circuit Court for further proceedings. Upon filing the mandate in the Circuit Court, the defendants moved that they have judgment against the …","sumSrc":"Headnote (U.S. Reports)","by":{"8":"18"}},{"t":"case","label":"Pers. Adm’r of Mass. v. Feeney","cite":"442 U.S. 256","y":1979,"id":"1978/78-233","sc":1,"sum":"The Court held that the law was enacted to serve \"legitimate and worthy purposes\" and not to discriminate on the basis of sex. Even though few women benefitted from the scheme, Justice Stewart argued that \"veteran status is not uniquely male.\" Furthermore, the law placed many men who were not veterans at a disadvantage as well.","sumSrc":"Oyez","by":{"8":"14"}},{"t":"case","label":"Shady Grove Orthopedic Assocs., P.A. v. Allstate Ins. Co.","cite":"559 U.S. 393","y":2010,"id":"2009/08-1008","sc":1,"sum":"The Court held that Section 901(b) of the New York Rules of Civil Procedure does not preclude a federal court ruling on entities from different jurisdictions from hearing a class action under Rule 23 of the Federal Rules of Civil Procedure.","sumSrc":"Oyez","by":{"8":"14"}},{"t":"case","label":"U.S. Army Corps of Eng’rs v. Hawkes Co.","cite":"578 U.S. 590","y":2016,"id":"2015/15-290","sc":1,"sum":"The Court determined that the Army Corps of Engineers’ jurisdictional determination that a property constituted “water of the United States” was a final agency action subject to judicial review under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"8":"21"}},{"t":"case","label":"United States v. Villamonte-Marquez","cite":"462 U.S. 579","y":1983,"id":"1982/81-1350","sc":1,"sum":"The action of the customs officers in boarding the sailboat pursuant to § 1581(a) was \"reasonable,\" and was therefore consistent with the Fourth Amendment. Although no Act of Congress can authorize a violation of the Constitution, in 1790, in a lineal ancestor to § 1581(a), the First Congress clearly authorized the suspicionless boarding of vessels by Government officers, reflecting its view that such boardings are …","sumSrc":"Syllabus (U.S. Reports)","by":{"8":"19"}},{"t":"case","label":"City of Chicago v. Fulton","cite":"141 S. Ct. 585","y":2021,"id":"2020/19-357","sc":1,"sum":"The mere retention of estate property after the filing of a bankruptcy petition does not violate 11 U. S. C. §362(a)(3), which operates as a “stay” of “any act” to “exercise control” over the property of the estate.","sumSrc":"Holding (supremecourt.gov)","by":{"9":"21"}},{"t":"case","label":"Friends of the Earth v. Laidlaw Envt’l Servs., Inc.","cite":"528 U.S. 167","y":2000,"id":"1999/98-822","sc":1,"op":2,"sum":"The Court held that a citizen suitor's claim for civil penalties need not be dismissed as moot when the defendant, after commencement of the litigation, has come into compliance with its NPDES permit. \"A defendant's voluntary cessation of allegedly unlawful conduct ordinarily does not suffice to moot a case,\" Justice Ginsburg wrote for the Court. \"Congress has found that civil penalties in the Clean Water Act cases do more than promote immediate compliance... they also deter future violations,\" concluded Justice Ginsburg.","sumSrc":"Oyez","by":{"9":"22","11":"18, 19"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"sum":"The near-unanimous Court held that the means of selecting the independent counsel did not violate the Appointments Clause; the powers allocated to the special court did not violate Article III; and the Act was not offensive to the separation of powers doctrine since it did not impermissibly interfere with the functions of the Executive Branch.","sumSrc":"Oyez","by":{"9":"8"}},{"t":"usc","label":"42 U.S.C. § 7416","url":"https://www.law.cornell.edu/uscode/text/42/7416","ar":1,"by":{"9":"6"}},{"t":"reg","label":"40 C.F.R. § 60.5710","url":"https://www.ecfr.gov/current/title-40/section-60.5710","by":{"9":"21"}},{"t":"reg","label":"40 C.F.R. § 60.5740","url":"https://www.ecfr.gov/current/title-40/section-60.5740","by":{"9":"20"}},{"t":"reg","label":"40 C.F.R. § 60.6855","url":"https://www.ecfr.gov/current/title-40/section-60.6855","by":{"9":"20"}},{"t":"reg","label":"80 Fed. Reg. 64,966","url":"https://www.govinfo.gov/link/fr/80/64966","by":{"9":"11"}},{"t":"reg","label":"85 Fed. Reg. 18,448","url":"https://www.govinfo.gov/link/fr/85/18448","by":{"9":"10"}},{"t":"case","label":"Bowen v. Mich. Academy of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"10":"13"}},{"t":"case","label":"Cohens v. Virginia","cite":"19 U.S. 264","y":1821,"id":"1789-1850/19us264","sc":1,"sum":"The Court decided it had jurisdiction over all cases involving Constitutional questions, including state supreme court decisions.","sumSrc":"Oyez","by":{"10":"14, 15"}},{"t":"case","label":"Marbury v. Madison","cite":"5 U.S. 137","y":1803,"id":"1789-1850/5us137","sc":1,"op":6,"sum":"A case in which the Court established a precedent for judicial review in the United States, declaring that acts of Congress that conflict with the Constitution are null and void, as the Constitution is the supreme law of the land.","sumSrc":"Oyez","by":{"10":"5"}},{"t":"case","label":"National Cable Telecom. Assn. v. Brand X Internet Services","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"sum":"The Court held that the FCC lawfully construed the Communications Act to not define cable broadband providers as \"telecommunications services.\" The Court held that the Ninth Circuit should have followed the Supreme Court's 1984 decision in Chevron v. Natural Resources Defense Council.","sumSrc":"Oyez","by":{"10":"16"}},{"t":"case","label":"Summers v. Earth Island Inst.","cite":"555 U.S. 488","y":2009,"id":"2008/07-463","sc":1,"sum":"The Court held that the defendants did not have standing to challenge regulations of the U.S. Forest Service in the absence of a live dispute over the application of those regulations.","sumSrc":"Oyez","by":{"10":"6"}},{"t":"case","label":"United States National Bank v. Independent Insurance Agents of America, Inc.","cite":"508 U.S. 439","y":1993,"id":"1992/92-484","sc":1,"sum":"The Act of Sept. 7, 1916, 39 Stat. 753 (1916 Act), among other things, authorized any national bank doing business in a community with a population not exceeding 5,000 to act as the agent for any insurance company. Although early editions of the United States Code included this provision as section 92 of Title 12 (section 92), the 1952 Code and subsequent editions omitted section 92 with a note indicating that …","sumSrc":"Syllabus (U.S. Reports)","by":{"10":"14, 15"}},{"t":"case","label":"Adarand Constructors, Inc. v. Slater","cite":"528 U.S. 216","y":2000,"id":"1999/99-295","sc":1,"op":2,"sum":"The Court held that \"[b]ecause, under the circumstances of this case, it is impossible to conclude that respondents have borne their burden of establishing that it is 'absolutely clear that the allegedly wrongful behavior could not reasonably be expected to recur,' [Adarand's] cause of action remains alive.\" \"It is no small matter to deprive a litigant of the rewards of its efforts,\" concluded the opinion, \"[s]uch action on grounds of mootness would be justified only if it were absolutely clear that the litigant no longer had any need of the judicial protection that it sought.\".","sumSrc":"Oyez","by":{"11":"19"}},{"t":"case","label":"Babbitt v. UFW Nat’l Union","cite":"442 U.S. 289","y":1979,"id":"1978/78-225","sc":1,"sum":"Appellees (a farmworkers' union, a union agent, farmworkers, and a union supporter) brought suit in Federal District Court in Arizona seeking a declaration of the unconstitutionality of various provisions of Arizona's farm labor statute, as well as of the entire statute, and an injunction against \"its enforcement. A three-judge court ruled unconstitutional on various grounds the provisions (1) specifying procedures …","sumSrc":"Syllabus (U.S. Reports)","by":{"11":"21"}},{"t":"case","label":"Champion Int’l Corp. v. EPA","cite":"850 F.2d 182","y":1988,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/850/182/","sum":"Holding that district court “properly inquired whether EPA had exceeded its delegated authority” despite claims of prematurity.","sumSrc":"brief:11","by":{"11":"22"}},{"t":"case","label":"Davis v. Fed. Election Comm’n","cite":"554 U.S. 724","y":2008,"id":"2007/07-320","sc":1,"sum":"Although all nine Justices agreed that Davis had standing to argue his case before the Court, only a 5-4 majority held that the contribution limits violated the First Amendment. In his majority opinion, Justice Samuel Alito noted that the Court had never upheld the constitutionality of a law imposing different contribution limits for candidates competing against one another.","sumSrc":"Oyez","by":{"11":"19"}},{"t":"case","label":"Dirks v. SEC","cite":"463 U.S. 646","y":1983,"id":"1982/82-276","sc":1,"sum":"The Court held that the duty to disclose information arises from a financial relationship with one of the parties, not just the possession of information. The Court also held that an insider is only liable for inside trading when he makes a profit on the information before disclosing.","sumSrc":"Oyez","by":{"11":"11"}},{"t":"case","label":"Genesis Healthcare Corp. v. Symczyk","cite":"569 U.S. 66","y":2013,"id":"2012/11-1059","sc":1,"op":1,"sum":"The Court held that a collective action suit on behalf of other \"similarly situated\" employees becomes moot when the individual claim does.","sumSrc":"Oyez","by":{"11":"18"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"op":1,"sum":"In addition to emphasizing Missouri's, or any other state's, Tenth Amendment right to define the qualifications of its highest state officials, the Court held that the regulations of the ADEA did not apply to \"policy-making\" appointees such as state court judges.","sumSrc":"Oyez","by":{"11":"8"}},{"t":"case","label":"Grupo Dataflux v. Atlas Glob. Grp., L.P.","cite":"541 U.S. 567","y":2004,"id":"2003/02-1689","sc":1,"sum":"In a 5-to-4 decision written by Justice Antonin Scalia, the Court ruled that allowing diversity jurisdiction to change after a case is filed would create uncertainty and expensive litigation that dealt with jurisdiction rather than the merits of the case. \"Uncertainty regarding the question of jurisdiction is particularly undesirable, and collateral litigation on the point particularly wasteful,\" wrote Justice Scalia. \"The stability provided by our time tested rule (of requiring diversity at the time of filing) weighs heavily against the approval of any new deviation.\".","sumSrc":"Oyez","by":{"11":"20-21"}},{"t":"case","label":"Holloway v. United States","cite":"526 U.S. 1","y":1999,"id":"1998/97-7164","sc":1,"sum":"Announced by Justice John Paul Stevens, the Court ruled that the federal carjacking law applies to carjacking crimes committed with \"conditional intent\" of harming drivers who refuse a carjacker's demands. \"The intent requirement...is satisfied when the government proves that at the moment the defendant demanded or took control over the driver's automobile the defendant possessed the intent to seriously harm or kill the driver if necessary to steal the car,\" wrote Justice Stevens.","sumSrc":"Oyez","by":{"11":"11"}},{"t":"case","label":"Karcher v. May","cite":"484 U.S. 72","y":1987,"id":"1987/85-1551","sc":1,"sum":"The Court held that once the individuals left their offices, the authority to pursue the lawsuit on behalf of the Legislature passed to their successors. Because Karcher and Orechio’s successors withdrew the appeal, there was no longer an active case or controversy, so the Court had no jurisdiction to hear the case under Article III.","sumSrc":"Oyez","by":{"11":"18"}},{"t":"case","label":"Kokoszka v. Belford","cite":"417 U.S. 642","y":1974,"id":"1973/73-5265","sc":1,"sum":"1. An income tax refund is \"property\" that passes to the trustee under § 70a (5) of the Bankruptcy Act, being \"sufficiently rooted in the bankruptcy past,\" and not being related conceptually to or the equivalent of future wages for the purpose of giving the bankrupt wage earner a \"fresh start.\" Lines v. Frederick, 400 U. S. 18, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"11":"11"}},{"t":"case","label":"Leedom v. Kyne","cite":"358 U.S. 184","y":1958,"id":"1958/14","sc":1,"sum":"A Federal District Court had jurisdiction of an original suit to set aside the Board's determination because it was made in excess of the Board's powers. Pp. 184-191. 101 U. S. App. D. C. 398, 249 F. 2d 490, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"11":"21-22"}},{"t":"case","label":"Mass. Mut. Life Ins. Co. v. Russell","cite":"473 U.S. 134","y":1985,"id":"1984/84-9","sc":1,"sum":"Section 409(a) does not provide a cause of action for extracontractual damages to a beneficiary caused by improper or untimely processing of benefit claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"11":"10"}},{"t":"case","label":"New Process Steel, L.P. v. NLRB","cite":"560 U.S. 674","y":2010,"id":"2009/08-1457","sc":1,"sum":"The Court held that the National Labor Relations Board cannot execute duties with only two members on its board when 29 U.S.C. Section 153(b) mandates that quorum for the board is three members.","sumSrc":"Oyez","by":{"11":"10"}},{"t":"case","label":"NLRB v. Ins. Agents’ Int’l Union, AFL-CIO","cite":"361 U.S. 477","y":1960,"id":"1959/15","sc":1,"sum":"Such tactics would not support a finding by the Board that the union had failed to bargain in good faith as required by § 8 (b) (3). Pp. 478-500. (1) The basic premise of the duty of collective bargaining required in the Act is that it is a process in which the parties deal with each other in a serious, good-faith desire to reach agreement and to enter into a contract ordering their industrial relationship. Congress …","sumSrc":"Syllabus (U.S. Reports)","by":{"11":"10"}},{"t":"case","label":"Port of Bos. Marine Terminal Ass’n v. Rederiaktiebolaget Transatlantic","cite":"400 U.S. 62","y":1970,"id":"1970/99","sc":1,"sum":"Petitioner Terminal Association, a maritime terminal operators conference. operating under an agreement approved by the Federal Maritime Commission (FMC), pursuant to §.15 of the Shipping Act, 1916, revised a tariff on file with the agency by shifting the incidence of a wharf demuri'age charge from consignees to carriers. When several carriers refused to pay the revised charge, which -had not previously been …","sumSrc":"Syllabus (U.S. Reports)","by":{"11":"21"}},{"t":"case","label":"Portland Cement Ass’n v. Ruckelshaus","cite":"486 F.2d 375","y":1973,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/486/375/","by":{"11":"16-17"}},{"t":"case","label":"Pub. Citizen v. U.S. Dep’t of Justice","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"sum":"To aid the President in fulfilling his constitutional duty to appoint federal judges, the Department of Justice regularly seeks advice from the Standing Committee on Federal Judiciary of the American Bar Association (ABA) regarding potential nominees for judgeships. The ABA Committee's investigations, reports, and votes on potential nominees are kept confidential, although its rating of a particular candidate is …","sumSrc":"Syllabus (U.S. Reports)","by":{"11":"12"}},{"t":"case","label":"Rimini St., Inc. v. Oracle USA, Inc.","cite":"139 S. Ct. 873","y":2019,"id":"2018/17-1625","sc":1,"sum":"A federal district court’s discretion to award “full costs” to a party in copyright litigation pursuant to 17 U. S. C. §505 is limited to the six categories specified in the general costs statute codified at 28 U. S. C. §§1821 and 1920.","sumSrc":"Holding (supremecourt.gov)","by":{"11":"12"}},{"t":"case","label":"Sackett v. EPA","cite":"566 U.S. 120","y":2012,"id":"2011/10-1062","sc":1,"sum":"The Court found that homeowners have a right to go to court over a Clean Water Act order of the Environmental Protection Agency.","sumSrc":"Oyez","by":{"11":"21"}},{"t":"case","label":"Small v. United States","cite":"544 U.S. 385","y":2005,"id":"2004/03-750","sc":1,"sum":"The Court held that the federal law's phrase, \"convicted in any court,\" encompassed only domestic, not foreign, convictions. The majority reasoned that in determining the scope of the phrase, it was appropriate to assume Congress had domestic concerns in mind. Moreover, the statute's overall language suggested no intent to reach beyond domestic convictions.","sumSrc":"Oyez","by":{"11":"11"}},{"t":"case","label":"United States v. Sisson","cite":"399 U.S. 267","y":1970,"id":"1969/305","sc":1,"sum":"Appellee was indicted for wilfully failing to report for induction as ordered by his local draft board. He moved to dismiss the indictment because (1) the involvement in Vietnam violated international law, (2) he \"reasonably believed the government's involvement in Vietnam to be illegal,\" (3) the Selective Service Act and its regulations were unconstitutional, as the local boards' procedures lacked due process, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"11":"16"}},{"t":"case","label":"Uzuegbunam v. Preczewski","cite":"141 S. Ct. 792","y":2021,"id":"2020/19-968","sc":1,"sum":"A request for nominal damages satisfies the redressability element necessary for Article III standing where a plaintiff’s claim is based on a completed violation of a legal right.","sumSrc":"Holding (supremecourt.gov)","by":{"11":"19, 22"}},{"t":"case","label":"Virginia v. Am. Booksellers Ass’n, Inc.","cite":"484 U.S. 383","y":1988,"id":"1987/86-1034","sc":1,"sum":"A 1985 amendment to a Virginia statute makes it unlawful for any person \"to knowingly display for commercial purposes in a manner whereby juveniles may examine and peruse\" certain visual or written sexual or sadomasochistic material that is harmful to juveniles. What is \"harmful to juveniles\" is defined elsewhere in the statute. Plaintiffs, a number of booksellers' organizations and two Virginia non-\"adults only,\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"11":"20"}},{"t":"case","label":"West Virginia v. EPA","cite":"362 F.3d 861","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/362/861/","by":{"11":"20"}},{"t":"reg","label":"86 Fed. Reg. 63,110","url":"https://www.govinfo.gov/link/fr/86/63110","by":{"11":"11"}}]};